import * as THREE from 'three'

export const TAU = Math.PI * 2
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]
export const chance = (p) => Math.random() < p
export const dist2 = (ax, az, bx, bz) => Math.hypot(ax - bx, az - bz)

export function wrapAngle(a) {
  return ((a + Math.PI) % TAU + TAU) % TAU - Math.PI
}

export function dampAngle(a, b, lambda, dt) {
  const d = wrapAngle(b - a)
  return a + d * (1 - Math.exp(-lambda * dt))
}

export function makeCanvas(w, h) {
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  return c
}

function finishTexture(canvas, repeat = 1) {
  const t = new THREE.CanvasTexture(canvas)
  t.colorSpace = THREE.SRGBColorSpace
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(repeat, repeat)
  t.anisotropy = 4
  return t
}

export function asphaltTexture() {
  const c = makeCanvas(512, 512)
  const x = c.getContext('2d')
  x.fillStyle = '#2b2c30'
  x.fillRect(0, 0, 512, 512)
  for (let i = 0; i < 22000; i++) {
    const g = 20 + Math.random() * 45
    x.fillStyle = `rgba(${g},${g},${g + 3},${Math.random() * 0.5})`
    x.fillRect(Math.random() * 512, Math.random() * 512, 1 + Math.random() * 2, 1 + Math.random() * 2)
  }
  for (let i = 0; i < 12; i++) {
    x.strokeStyle = `rgba(15,15,17,${0.25 + Math.random() * 0.3})`
    x.lineWidth = 0.6 + Math.random()
    x.beginPath()
    let px = Math.random() * 512
    let py = Math.random() * 512
    x.moveTo(px, py)
    for (let s = 0; s < 6; s++) {
      px += (Math.random() - 0.5) * 60
      py += Math.random() * 30
      x.lineTo(px, py)
    }
    x.stroke()
  }
  return finishTexture(c, 90)
}

export function concreteTexture() {
  const c = makeCanvas(256, 256)
  const x = c.getContext('2d')
  x.fillStyle = '#8b8b8f'
  x.fillRect(0, 0, 256, 256)
  for (let i = 0; i < 7000; i++) {
    const g = 110 + Math.random() * 50
    x.fillStyle = `rgba(${g},${g},${g},${Math.random() * 0.4})`
    x.fillRect(Math.random() * 256, Math.random() * 256, 1.5, 1.5)
  }
  x.strokeStyle = 'rgba(60,60,64,0.55)'
  x.lineWidth = 1.5
  for (let i = 0; i <= 4; i++) {
    x.beginPath(); x.moveTo(i * 64, 0); x.lineTo(i * 64, 256); x.stroke()
    x.beginPath(); x.moveTo(0, i * 64); x.lineTo(256, i * 64); x.stroke()
  }
  return finishTexture(c, 1)
}

export function sandTexture() {
  const c = makeCanvas(256, 256)
  const x = c.getContext('2d')
  x.fillStyle = '#c9aa78'
  x.fillRect(0, 0, 256, 256)
  for (let i = 0; i < 14000; i++) {
    const g = Math.random()
    x.fillStyle = g > 0.5 ? 'rgba(235,214,170,0.35)' : 'rgba(130,104,68,0.28)'
    x.fillRect(Math.random() * 256, Math.random() * 256, 1.5, 1.5)
  }
  for (let i = 0; i < 10; i++) {
    x.strokeStyle = 'rgba(150,124,86,0.25)'
    x.beginPath()
    x.moveTo(0, Math.random() * 256)
    x.bezierCurveTo(80, Math.random() * 256, 160, Math.random() * 256, 256, Math.random() * 256)
    x.stroke()
  }
  return finishTexture(c, 20)
}

export function grassTexture() {
  const c = makeCanvas(256, 256)
  const x = c.getContext('2d')
  x.fillStyle = '#3e6534'
  x.fillRect(0, 0, 256, 256)
  for (let i = 0; i < 16000; i++) {
    const g = Math.random()
    x.fillStyle = g > 0.5 ? 'rgba(100,140,70,0.5)' : 'rgba(30,55,28,0.5)'
    x.fillRect(Math.random() * 256, Math.random() * 256, 1.5, 2.5)
  }
  return finishTexture(c, 30)
}

// Architectural facade: 3 window bays by 2 floors per texture tile.
export function facadeTextures(style) {
  const size = 256
  const base = makeCanvas(size, size)
  const emit = makeCanvas(size, size)
  const b = base.getContext('2d')
  const e = emit.getContext('2d')
  b.fillStyle = '#ffffff'
  b.fillRect(0, 0, size, size)
  e.fillStyle = '#000000'
  e.fillRect(0, 0, size, size)

  const palettes = [
    { wall: '#9aa2ac', mullion: '#5d6670', glass: '#33404d', light: '#ffd9a0' },
    { wall: '#c0ab92', mullion: '#7e6d5a', glass: '#3a3d42', light: '#ffe0a8' },
    { wall: '#8f6a5c', mullion: '#5f443c', glass: '#332f33', light: '#ffc987' },
    { wall: '#a8b3b5', mullion: '#606e72', glass: '#2f4148', light: '#bfe8ff' }
  ]
  const p = palettes[style % palettes.length]
  b.fillStyle = p.wall
  b.fillRect(0, 0, size, size)
  // subtle facade grain
  for (let i = 0; i < 1800; i++) {
    b.fillStyle = `rgba(0,0,0,${Math.random() * 0.05})`
    b.fillRect(Math.random() * size, Math.random() * size, 2, 2)
  }
  const cols = 3
  const rows = 2
  for (let r = 0; r < rows; r++) {
    for (let cIdx = 0; cIdx < cols; cIdx++) {
      const w = size / cols
      const h = size / rows
      const x0 = cIdx * w + w * 0.16
      const y0 = r * h + h * 0.18
      const ww = w * 0.68
      const hh = h * 0.58
      b.fillStyle = p.mullion
      b.fillRect(x0 - 3, y0 - 3, ww + 6, hh + 6)
      b.fillStyle = p.glass
      b.fillRect(x0, y0, ww, hh)
      b.fillStyle = 'rgba(255,255,255,0.09)'
      b.fillRect(x0, y0, ww, hh * 0.22)
      if (Math.random() < 0.48) {
        const lit = p.light
        e.fillStyle = lit
        e.fillRect(x0, y0, ww, hh)
        e.fillStyle = 'rgba(0,0,0,0.35)'
        e.fillRect(x0 + ww * 0.46, y0, ww * 0.08, hh)
      }
      if (style === 1) {
        // balconies
        b.fillStyle = 'rgba(45,40,36,0.55)'
        b.fillRect(x0 - 8, y0 + hh + 4, ww + 16, 7)
      }
    }
    // floor slab
    b.fillStyle = 'rgba(40,42,45,0.32)'
    b.fillRect(0, r * (size / rows) + size / rows - 7, size, 6)
  }
  return { map: finishTexture(base), emissive: finishTexture(emit) }
}

export function neonTexture(text, color = '#ff4fa3') {
  const c = makeCanvas(512, 128)
  const x = c.getContext('2d')
  x.clearRect(0, 0, 512, 128)
  x.font = 'bold 64px Arial Black, Arial, sans-serif'
  x.textAlign = 'center'
  x.textBaseline = 'middle'
  x.shadowColor = color
  x.shadowBlur = 26
  x.fillStyle = color
  x.fillText(text, 256, 66)
  x.shadowBlur = 10
  x.fillStyle = '#ffffff'
  x.globalAlpha = 0.85
  x.fillText(text, 256, 66)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

let glowTex = null
export function glowTexture() {
  if (glowTex) return glowTex
  const c = makeCanvas(128, 128)
  const x = c.getContext('2d')
  const g = x.createRadialGradient(64, 64, 0, 64, 64, 64)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.22, 'rgba(255,255,255,0.65)')
  g.addColorStop(0.55, 'rgba(255,255,255,0.16)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  x.fillStyle = g
  x.fillRect(0, 0, 128, 128)
  glowTex = new THREE.CanvasTexture(c)
  glowTex.colorSpace = THREE.SRGBColorSpace
  return glowTex
}

export function glowSprite(color = 0xffffff, size = 4, opacity = 0.8) {
  const s = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture(),
    color,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false
  }))
  s.scale.set(size, size, 1)
  return s
}

export function disposeObject(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose?.()
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material]
      for (const m of mats) {
        if (m.map) m.map.dispose?.()
        m.dispose?.()
      }
    }
  })
}

export function formatMoney(n) {
  return '$' + Math.floor(n).toLocaleString('en-US')
}

// Fully synthesized audio: no external assets.
export class GameAudio {
  constructor() {
    this.ctx = null
    this.master = null
    this.engine = null
    this.siren = null
    this.muted = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.32
    this.master.connect(this.ctx.destination)

    // Engine: detuned saw pair through a lowpass.
    const eGain = this.ctx.createGain()
    eGain.gain.value = 0
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 220
    filter.Q.value = 2
    const oscA = this.ctx.createOscillator()
    oscA.type = 'sawtooth'
    oscA.frequency.value = 55
    const oscB = this.ctx.createOscillator()
    oscB.type = 'square'
    oscB.frequency.value = 41
    const bGain = this.ctx.createGain()
    bGain.gain.value = 0.5
    oscA.connect(filter)
    oscB.connect(bGain)
    bGain.connect(filter)
    filter.connect(eGain)
    eGain.connect(this.master)
    oscA.start()
    oscB.start()
    this.engine = { gain: eGain, filter, oscA, oscB }

    // Siren: two-tone oscillator.
    const sGain = this.ctx.createGain()
    sGain.gain.value = 0
    const sOsc = this.ctx.createOscillator()
    sOsc.type = 'triangle'
    sOsc.frequency.value = 720
    const sFilter = this.ctx.createBiquadFilter()
    sFilter.type = 'bandpass'
    sFilter.frequency.value = 900
    sFilter.Q.value = 1.2
    sOsc.connect(sFilter)
    sFilter.connect(sGain)
    sGain.connect(this.master)
    sOsc.start()
    this.siren = { gain: sGain, osc: sOsc, filter: sFilter, t: 0, active: false }
    this.noise = this.makeNoiseBuffer()
  }

  makeNoiseBuffer() {
    const len = this.ctx.sampleRate * 1.2
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    return buf
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.value = m ? 0 : 0.32
  }

  setEngine(speedRatio, throttle) {
    if (!this.engine) return
    const t = this.ctx.currentTime
    const target = Math.min(1, speedRatio)
    this.engine.gain.gain.setTargetAtTime(target > 0.02 ? 0.09 + target * 0.1 : 0, t, 0.08)
    this.engine.filter.frequency.setTargetAtTime(160 + target * 900 + throttle * 300, t, 0.08)
    this.engine.oscA.frequency.setTargetAtTime(48 + target * 120, t, 0.06)
    this.engine.oscB.frequency.setTargetAtTime(36 + target * 92, t, 0.06)
  }

  updateSiren(dt, active) {
    if (!this.siren) return
    const t = this.ctx.currentTime
    this.siren.gain.gain.setTargetAtTime(active ? 0.045 : 0, t, 0.18)
    if (active) {
      this.siren.t += dt
      const f = 640 + (Math.sin(this.siren.t * 6) * 0.5 + 0.5) * 420
      this.siren.osc.frequency.setTargetAtTime(f, t, 0.03)
    }
  }

  noiseBurst(duration, gain, filterType, freqStart, freqEnd) {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const f = this.ctx.createBiquadFilter()
    f.type = filterType
    f.frequency.setValueAtTime(freqStart, t)
    f.frequency.exponentialRampToValueAtTime(Math.max(40, freqEnd), t + duration)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(f)
    f.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + duration + 0.05)
  }

  gunshot() {
    if (!this.ctx) return
    this.noiseBurst(0.16, 0.5, 'lowpass', 4200, 320)
    const t = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = 'square'
    osc.frequency.setValueAtTime(140, t)
    osc.frequency.exponentialRampToValueAtTime(45, t + 0.12)
    g.gain.setValueAtTime(0.22, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.14)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.16)
  }

  explosion() {
    this.noiseBurst(1.1, 0.7, 'lowpass', 1600, 60)
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(80, t)
    osc.frequency.exponentialRampToValueAtTime(24, t + 0.8)
    g.gain.setValueAtTime(0.5, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.95)
  }

  thud() {
    this.noiseBurst(0.18, 0.3, 'lowpass', 700, 80)
  }

  hurt() {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = 'sawtooth'
    osc.frequency.setValueAtTime(180, t)
    osc.frequency.exponentialRampToValueAtTime(70, t + 0.2)
    g.gain.setValueAtTime(0.12, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.24)
  }

  pickup() {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    ;[660, 880, 1320].forEach((f, i) => {
      const osc = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      osc.type = 'sine'
      osc.frequency.value = f
      g.gain.setValueAtTime(0.0001, t + i * 0.07)
      g.gain.exponentialRampToValueAtTime(0.12, t + i * 0.07 + 0.015)
      g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.07 + 0.2)
      osc.connect(g)
      g.connect(this.master)
      osc.start(t + i * 0.07)
      osc.stop(t + i * 0.07 + 0.22)
    })
  }

  ui() {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = 'square'
    osc.frequency.setValueAtTime(520, t)
    osc.frequency.exponentialRampToValueAtTime(780, t + 0.07)
    g.gain.setValueAtTime(0.05, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.1)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.12)
  }

  reload() {
    this.noiseBurst(0.07, 0.18, 'highpass', 1800, 3000)
    setTimeout(() => this.noiseBurst(0.06, 0.14, 'highpass', 1200, 2200), 120)
  }

  notify(high = false) {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(high ? 880 : 440, t)
    osc.frequency.setValueAtTime(high ? 1320 : 660, t + 0.09)
    g.gain.setValueAtTime(0.07, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + 0.32)
  }
}

export class Input {
  constructor(canvas, touchRoot) {
    this.canvas = canvas
    this.touchRoot = touchRoot
    this.keys = new Set()
    this.actions = Object.create(null)
    this.pressed = new Set()
    this.lookDX = 0
    this.lookDY = 0
    this.firing = false
    this.aiming = false
    this.touchMove = { x: 0, y: 0 }
    this.touchActive = false
    this.isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0
    this.pointerLocked = false
    this.stickPointer = null
    this.lookPointer = null
    this.lookStart = { x: 0, y: 0 }
    this._bind()
  }

  _bind() {
    const down = (e) => {
      if (e.target.closest?.('button, input, a')) return
      this.keys.add(e.code)
      if (!e.repeat) {
        if (e.code === 'KeyE') this.pressed.add('enter')
        if (e.code === 'Space') { this.pressed.add('jump'); e.preventDefault() }
        if (e.code === 'KeyR') this.pressed.add('reload')
        if (e.code === 'KeyM') this.pressed.add('mute')
        if (e.code === 'Escape') this.pressed.add('pause')
        if (e.code === 'KeyC') this.pressed.add('camera')
      }
    }
    const up = (e) => this.keys.delete(e.code)
    window.addEventListener('keydown', down)
    window.addEventListener('keyup', up)
    window.addEventListener('blur', () => { this.keys.clear(); this.firing = false; this.aiming = false })

    window.addEventListener('mousemove', (e) => {
      if (this.pointerLocked) {
        this.lookDX += e.movementX
        this.lookDY += e.movementY
      } else if (this.lookPointer === 'mouse') {
        this.lookDX += e.movementX
        this.lookDY += e.movementY
      }
    })
    this.canvas.addEventListener('mousedown', (e) => {
      if (e.button === 0) this.firing = true
      if (e.button === 2) this.aiming = true
      if (!this.pointerLocked && !this.isTouch) {
        this.lookPointer = 'mouse'
        try { this.canvas.requestPointerLock?.() } catch { /* ignore */ }
      }
    })
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.firing = false
      if (e.button === 2) this.aiming = false
      if (this.lookPointer === 'mouse') this.lookPointer = null
    })
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault())
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas
    })

    // Touch: left joystick, right side drag to look, buttons.
    const stickBase = this.touchRoot?.querySelector('#stick-base')
    const stickKnob = this.touchRoot?.querySelector('#stick-knob')
    if (stickBase) {
      const updateStick = (e) => {
        const r = stickBase.getBoundingClientRect()
        const cx = r.left + r.width / 2
        const cy = r.top + r.height / 2
        let dx = e.clientX - cx
        let dy = e.clientY - cy
        const max = r.width * 0.42
        const len = Math.hypot(dx, dy)
        if (len > max) { dx = dx / len * max; dy = dy / len * max }
        this.touchMove.x = dx / max
        this.touchMove.y = dy / max
        stickKnob.style.transform = `translate(${dx}px, ${dy}px)`
      }
      stickBase.addEventListener('pointerdown', (e) => {
        e.preventDefault()
        this.stickPointer = e.pointerId
        stickBase.setPointerCapture(e.pointerId)
        updateStick(e)
      })
      stickBase.addEventListener('pointermove', (e) => {
        if (this.stickPointer !== e.pointerId) return
        updateStick(e)
      })
      const endStick = (e) => {
        if (this.stickPointer !== e.pointerId) return
        this.stickPointer = null
        this.touchMove.x = 0
        this.touchMove.y = 0
        stickKnob.style.transform = 'translate(0px, 0px)'
      }
      stickBase.addEventListener('pointerup', endStick)
      stickBase.addEventListener('pointercancel', endStick)
    }

    this.canvas.addEventListener('touchstart', (e) => {
      if (this.lookPointer !== null) return
      const t = e.changedTouches[0]
      this.lookPointer = t.identifier
      this.lookStart.x = t.clientX
      this.lookStart.y = t.clientY
    }, { passive: true })
    this.canvas.addEventListener('touchmove', (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier !== this.lookPointer) continue
        const dx = t.clientX - this.lookStart.x
        const dy = t.clientY - this.lookStart.y
        this.lookStart.x = t.clientX
        this.lookStart.y = t.clientY
        this.lookDX += dx * 1.35
        this.lookDY += dy * 1.35
      }
    }, { passive: true })
    const endLook = (e) => {
      for (const t of e.changedTouches) if (t.identifier === this.lookPointer) this.lookPointer = null
    }
    this.canvas.addEventListener('touchend', endLook, { passive: true })
    this.canvas.addEventListener('touchcancel', endLook, { passive: true })

    for (const btn of this.touchRoot?.querySelectorAll('[data-action]') || []) {
      const action = btn.dataset.action
      if (action === 'fire' || action === 'aim' || action === 'sprint') {
        const on = (e) => {
          e.preventDefault()
          btn.classList.add('held')
          if (action === 'fire') this.firing = true
          else if (action === 'aim') this.aiming = true
          else this.actions.sprint = true
        }
        const off = (e) => {
          e.preventDefault()
          btn.classList.remove('held')
          if (action === 'fire') this.firing = false
          else if (action === 'aim') this.aiming = false
          else this.actions.sprint = false
        }
        btn.addEventListener('pointerdown', on)
        btn.addEventListener('pointerup', off)
        btn.addEventListener('pointercancel', off)
        btn.addEventListener('pointerleave', off)
      } else {
        btn.addEventListener('pointerdown', (e) => {
          e.preventDefault()
          this.pressed.add(action)
        })
      }
    }
  }

  setTouchMode(on) {
    this.isTouch = on
    document.body.classList.toggle('touch', on)
  }

  down(code) { return this.keys.has(code) }
  sprinting() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.actions.sprint }
  moveVector() {
    let x = 0
    let y = 0
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y += 1
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y -= 1
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1
    x += this.touchMove.x
    y -= this.touchMove.y
    const len = Math.hypot(x, y)
    if (len > 1) { x /= len; y /= len }
    return { x, y }
  }

  consumeLook() {
    const out = { x: this.lookDX, y: this.lookDY }
    this.lookDX = 0
    this.lookDY = 0
    return out
  }

  wasPressed(action) {
    if (!this.pressed.has(action)) return false
    this.pressed.delete(action)
    return true
  }

  endFrame() {
    this.pressed.clear()
  }
}

import * as THREE from 'three'
import {
  TAU, clamp, lerp, rand, randInt, pick, chance,
  asphaltTexture, concreteTexture, sandTexture, grassTexture,
  facadeTextures, neonTexture, glowTexture, glowSprite
} from './utils.js'

export const GRID = 70
export const CITY_EDGE = 350
export const ROAD_HALF = 9
export const BLOCK_HALF = 26
export const OCEAN_Z = 438

const FOG_DENSITY = 0.0019

export class World {
  constructor(scene, renderer) {
    this.scene = scene
    this.renderer = renderer
    this.group = new THREE.Group()
    scene.add(this.group)
    this.buildings = []
    this.buildingParts = [[], [], [], []]
    this.buildingMeshes = []
    this.colliders = []
    this.streetlights = []
    this.timeOfDay = 18.35
    this.dayLength = 640 // seconds per 24h
    this.nightFactor = 0
    this._t = 0
    this._lightTimer = 0
    this._textures = {}
    this._build()
  }

  _build() {
    this._makeSky()
    this._makeLights()
    this._makeGround()
    this._makeCity()
    this._makePark()
    this._makePlaza()
    this._makeCasino()
    this._makeStreetFurniture()
    this._makeBeach()
    this._makeDistant()
    this._makeCityLights()
  }

  _makeSky() {
    const geo = new THREE.SphereGeometry(880, 32, 20)
    this.skyUniforms = {
      topColor: { value: new THREE.Color(0x2c3a78) },
      horizonColor: { value: new THREE.Color(0xff945c) },
      sunDir: { value: new THREE.Vector3(0, 0.2, 0.3) },
      sunColor: { value: new THREE.Color(0xffd39a) }
    }
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: this.skyUniforms,
      vertexShader: /* glsl */`
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: /* glsl */`
        uniform vec3 topColor;
        uniform vec3 horizonColor;
        uniform vec3 sunDir;
        uniform vec3 sunColor;
        varying vec3 vDir;
        void main() {
          vec3 d = normalize(vDir);
          float h = clamp(d.y * 1.35 + 0.08, 0.0, 1.0);
          vec3 col = mix(horizonColor, topColor, pow(h, 0.62));
          float sd = max(dot(d, normalize(sunDir)), 0.0);
          col += sunColor * pow(sd, 420.0) * 2.2;
          col += sunColor * pow(sd, 9.0) * 0.22;
          gl_FragColor = vec4(col, 1.0);
        }`
    })
    this.sky = new THREE.Mesh(geo, mat)
    this.sky.frustumCulled = false
    this.scene.add(this.sky)

    this.sunSprite = glowSprite(0xffd9a0, 170, 0.95)
    this.sunSprite.material.depthWrite = false
    this.scene.add(this.sunSprite)

    // Soft cloud banks near the horizon.
    this.clouds = []
    const cloudColors = [0xffd0b0, 0xffb9a0, 0xc8a6c8]
    for (let i = 0; i < 12; i++) {
      const s = glowSprite(pick(cloudColors), rand(70, 160), rand(0.07, 0.16))
      const a = rand(0, TAU)
      const r = rand(280, 620)
      s.position.set(Math.cos(a) * r, rand(55, 130), Math.sin(a) * r)
      s.scale.y *= 0.33
      this.scene.add(s)
      this.clouds.push(s)
    }

    this.stars = null
    const starGeo = new THREE.BufferGeometry()
    const pos = []
    for (let i = 0; i < 900; i++) {
      const a = rand(0, TAU)
      const y = rand(0.12, 1)
      const r = Math.sqrt(1 - y * y) * 830
      pos.push(Math.cos(a) * r, y * 830, Math.sin(a) * r)
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3))
    this.starMat = new THREE.PointsMaterial({
      color: 0xdfe8ff, size: 1.9, sizeAttenuation: false, transparent: true, opacity: 0, depthWrite: false, fog: false
    })
    this.stars = new THREE.Points(starGeo, this.starMat)
    this.scene.add(this.stars)
    this.scene.fog = new THREE.FogExp2(0xbc8f82, FOG_DENSITY)
  }

  _makeLights() {
    this.hemi = new THREE.HemisphereLight(0x9fc4ff, 0x4c4038, 0.7)
    this.scene.add(this.hemi)
    this.sun = new THREE.DirectionalLight(0xffd0a0, 2.4)
    this.sun.castShadow = true
    this.sun.shadow.mapSize.set(2048, 2048)
    this.sun.shadow.camera.left = -95
    this.sun.shadow.camera.right = 95
    this.sun.shadow.camera.top = 95
    this.sun.shadow.camera.bottom = -95
    this.sun.shadow.camera.near = 1
    this.sun.shadow.camera.far = 420
    this.sun.shadow.bias = -0.0004
    this.sun.shadow.normalBias = 0.035
    this.scene.add(this.sun)
    this.scene.add(this.sun.target)

    this.lightPool = []
    for (let i = 0; i < 5; i++) {
      const l = new THREE.PointLight(0xffb35e, 0, 30, 2)
      this.scene.add(l)
      this.lightPool.push(l)
    }
    this.moon = new THREE.DirectionalLight(0x8ea6ff, 0)
    this.scene.add(this.moon)
  }

  _makeGround() {
    const asphalt = asphaltTexture()
    this._textures.asphalt = asphalt
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(1700, 1700),
      new THREE.MeshStandardMaterial({ map: asphalt, color: 0xffffff, roughness: 0.94, metalness: 0.04 })
    )
    ground.rotation.x = -Math.PI / 2
    ground.receiveShadow = true
    this.group.add(ground)
    this.ground = ground
  }

  _blockCenter(i, j) {
    return { x: GRID * i + GRID / 2, z: GRID * j + GRID / 2 }
  }

  _blockType(i, j) {
    if (i === 0 && j === 0) return 'plaza'
    if (i === -2 && j === 2) return 'park'
    if (i === 2 && j === -2) return 'casino'
    return 'city'
  }

  _makeCity() {
    const concrete = concreteTexture()
    this._textures.concrete = concrete
    const grass = grassTexture()
    this._textures.grass = grass

    const plateGeo = new THREE.BoxGeometry(52, 0.18, 52)
    const plateMat = new THREE.MeshStandardMaterial({ map: concrete, color: 0xb8b8bd, roughness: 0.95 })
    const parkMat = new THREE.MeshStandardMaterial({ map: grass, color: 0xffffff, roughness: 1 })
    const plates = new THREE.InstancedMesh(plateGeo, plateMat, 100)
    plates.receiveShadow = true
    const parkPlates = []
    let pi = 0
    let ppi = 0
    const m = new THREE.Matrix4()

    for (let i = -5; i < 5; i++) {
      for (let j = -5; j < 5; j++) {
        const type = this._blockType(i, j)
        const c = this._blockCenter(i, j)
        m.makeTranslation(c.x, 0.09, c.z)
        if (type === 'park') {
          parkPlates.push({ c })
          const p = new THREE.Mesh(new THREE.BoxGeometry(52, 0.2, 52), parkMat)
          p.position.set(c.x, 0.1, c.z)
          p.receiveShadow = true
          this.group.add(p)
          continue
        }
        plates.setMatrixAt(pi++, m)
        if (type === 'city') this._fillBlock(i, j)
      }
    }
    plates.count = pi
    plates.instanceMatrix.needsUpdate = true
    this.group.add(plates)

    this._mergeBuildings()

    // Lane dashes
    const dashGeo = new THREE.BoxGeometry(0.18, 0.02, 3.4)
    const dashMat = new THREE.MeshStandardMaterial({ color: 0xd9d4c2, roughness: 0.8, emissive: 0x222018, emissiveIntensity: 0.2 })
    const dashes = []
    for (let line = -5; line <= 5; line++) {
      const p = GRID * line
      for (let s = -5; s < 5; s++) {
        const mid = GRID * s + GRID / 2
        for (let k = -1.6; k <= 1.6; k++) {
          const off = k * 9.8
          if (Math.abs(off) < 2) continue
          dashes.push([p + off, mid])
          dashes.push([mid, p + off])
        }
      }
    }
    const dashMesh = new THREE.InstancedMesh(dashGeo, dashMat, dashes.length * 2)
    let di = 0
    for (const [x, z] of dashes) {
      m.makeTranslation(x, 0.021, z)
      dashMesh.setMatrixAt(di++, m)
      const rot = new THREE.Matrix4().makeRotationY(Math.PI / 2)
      rot.setPosition(x, 0.021, z)
      dashMesh.setMatrixAt(di++, rot)
    }
    dashMesh.count = di
    dashMesh.instanceMatrix.needsUpdate = true
    this.group.add(dashMesh)

    // Crosswalk stripes at every intersection.
    const cwGeo = new THREE.BoxGeometry(1.5, 0.02, 3.1)
    const cw = []
    for (let i = -5; i <= 5; i++) {
      for (let j = -5; j <= 5; j++) {
        const x = GRID * i
        const z = GRID * j
        for (let k = -3; k <= 3; k++) {
          if (Math.abs(k) < 1) continue
          cw.push([x + k * 2.2, z - 12.4, 0])
          cw.push([x + k * 2.2, z + 12.4, 0])
          cw.push([x - 12.4, z + k * 2.2, 1])
          cw.push([x + 12.4, z + k * 2.2, 1])
        }
      }
    }
    const cwMesh = new THREE.InstancedMesh(cwGeo, new THREE.MeshStandardMaterial({ color: 0xcfc9b8, roughness: 0.85 }), cw.length)
    for (let i = 0; i < cw.length; i++) {
      const [x, z, rot] = cw[i]
      if (rot) {
        const mat = new THREE.Matrix4().makeRotationY(Math.PI / 2)
        mat.setPosition(x, 0.022, z)
        cwMesh.setMatrixAt(i, mat)
      } else {
        m.makeTranslation(x, 0.022, z)
        cwMesh.setMatrixAt(i, m)
      }
    }
    cwMesh.instanceMatrix.needsUpdate = true
    this.group.add(cwMesh)

    // Curbs
    const curbMat = new THREE.MeshStandardMaterial({ color: 0x9d9da1, roughness: 0.9 })
    const curbGeo = new THREE.BoxGeometry(52.4, 0.3, 0.5)
    const curbs = new THREE.InstancedMesh(curbGeo, curbMat, 400)
    let ci = 0
    for (let i = -5; i < 5; i++) {
      for (let j = -5; j < 5; j++) {
        const c = this._blockCenter(i, j)
        if (this._blockType(i, j) === 'park') continue
        for (const [dx, dz, rot] of [[0, -26.2, 0], [0, 26.2, 0], [-26.2, 0, 1], [26.2, 0, 1]]) {
          const mat = rot ? new THREE.Matrix4().makeRotationY(Math.PI / 2) : new THREE.Matrix4()
          mat.setPosition(c.x + dx, 0.15, c.z + dz)
          curbs.setMatrixAt(ci++, mat)
        }
      }
    }
    curbs.count = ci
    curbs.instanceMatrix.needsUpdate = true
    this.group.add(curbs)
  }

  _fillBlock(i, j) {
    const c = this._blockCenter(i, j)
    const dist = Math.hypot(c.x, c.z)
    const downtown = clamp(1 - dist / 240, 0, 1)
    const beachfront = j >= 4
    const styles = [0, 1, 2, 3]

    const add = (x, z, w, d, h, style) => {
      const tint = new THREE.Color().setHSL(rand(0.05, 0.62), rand(0.02, 0.12), rand(0.55, 0.82))
      this._addBuilding(x, z, w, d, h, style, tint)
    }

    if (chance(0.18) && downtown > 0.25) {
      // Signature tower on the block
      const h = rand(55, 118) * (0.55 + downtown * 0.8)
      add(c.x, c.z, rand(28, 38), rand(28, 38), h, randInt(0, 3))
      return
    }

    const rows = chance(0.55) ? 2 : 1
    const cols = chance(0.55) ? 2 : 1
    const lot = 39
    const gap = 2.4
    const bw = (lot - gap * (cols - 1)) / cols
    const bd = (lot - gap * (rows - 1)) / rows
    for (let r = 0; r < rows; r++) {
      for (let col = 0; col < cols; col++) {
        if (rows * cols === 4 && chance(0.12)) continue
        const x = c.x - lot / 2 + bw / 2 + col * (bw + gap)
        const z = c.z - lot / 2 + bd / 2 + r * (bd + gap)
        let h
        if (beachfront) h = rand(9, 22)
        else h = rand(11, 30) + Math.pow(downtown, 2.2) * rand(25, 80)
        if (chance(0.05) && downtown > 0.3) h = rand(85, 125)
        add(x, z, bw * rand(0.86, 1), bd * rand(0.86, 1), h, pick(styles))
      }
    }
  }

  _addBuilding(x, z, w, d, h, style, tint, yBase = 0.18) {
    const geo = new THREE.BoxGeometry(w, h, d)
    geo.translate(0, h / 2, 0)
    const uv = geo.attributes.uv
    const color = new Float32Array(geo.attributes.position.count * 3)
    const roof = new THREE.Color(0x2c2c30)
    const side = tint
    for (let f = 0; f < 6; f++) {
      let su, sv
      if (f === 0 || f === 1) { su = d / 8; sv = h / 7 }
      else if (f === 4 || f === 5) { su = w / 8; sv = h / 7 }
      else { su = w / 8; sv = d / 8 }
      for (let k = 0; k < 4; k++) {
        const idx = f * 4 + k
        uv.setXY(idx, uv.getX(idx) * su, uv.getY(idx) * sv)
        const cc = (f === 2 || f === 3) ? roof : side
        color[idx * 3] = cc.r
        color[idx * 3 + 1] = cc.g
        color[idx * 3 + 2] = cc.b
      }
    }
    geo.setAttribute('color', new THREE.BufferAttribute(color, 3))
    geo.deleteAttribute('uv1')
    geo.deleteAttribute('uv2')
    const ng = geo.toNonIndexed()
    ng.translate(x, yBase, z)
    this.buildingParts[style].push(ng)
    geo.dispose()

    this.buildings.push({
      minX: x - w / 2, maxX: x + w / 2,
      minZ: z - d / 2, maxZ: z + d / 2,
      height: h + yBase, x, z, w, d, h
    })

    if (h > 18 && chance(0.4)) {
      this._roofProps = this._roofProps || []
      this._roofProps.push({ x, z, y: h + yBase, w, d })
    }
  }

  _mergeBuildings() {
    const mats = [0, 1, 2, 3].map((s) => {
      const tex = facadeTextures(s)
      this._textures['facade' + s] = tex
      return new THREE.MeshStandardMaterial({
        map: tex.map,
        emissiveMap: tex.emissive,
        emissive: 0xffffff,
        emissiveIntensity: 0,
        vertexColors: true,
        roughness: 0.82,
        metalness: 0.08
      })
    })
    this.buildingMaterials = mats
    for (let s = 0; s < 4; s++) {
      const parts = this.buildingParts[s]
      if (!parts.length) continue
      let vcount = 0
      for (const g of parts) vcount += g.attributes.position.count
      const pos = new Float32Array(vcount * 3)
      const nor = new Float32Array(vcount * 3)
      const uv = new Float32Array(vcount * 2)
      const col = new Float32Array(vcount * 3)
      let o = 0
      for (const g of parts) {
        const n = g.attributes.position.count
        pos.set(g.attributes.position.array, o * 3)
        nor.set(g.attributes.normal.array, o * 3)
        uv.set(g.attributes.uv.array, o * 2)
        col.set(g.attributes.color.array, o * 3)
        o += n
        g.dispose()
      }
      const geo = new THREE.BufferGeometry()
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
      geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3))
      geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
      geo.setAttribute('color', new THREE.BufferAttribute(col, 3))
      geo.computeBoundingSphere()
      const mesh = new THREE.Mesh(geo, mats[s])
      mesh.castShadow = true
      mesh.receiveShadow = true
      this.group.add(mesh)
      this.buildingMeshes.push(mesh)
      this.colliders.push(mesh)
    }

    // Rooftop AC units and antennas.
    const props = this._roofProps || []
    const acGeo = new THREE.BoxGeometry(1, 1, 1)
    const acMat = new THREE.MeshStandardMaterial({ color: 0x6a6c70, roughness: 0.9 })
    const acMesh = new THREE.InstancedMesh(acGeo, acMat, props.length * 2)
    acMesh.castShadow = true
    const m = new THREE.Matrix4()
    const q = new THREE.Quaternion()
    const sc = new THREE.Vector3()
    const pv = new THREE.Vector3()
    let n = 0
    for (const p of props) {
      for (let k = 0; k < 2; k++) {
        if (chance(0.35)) continue
        pv.set(p.x + rand(-p.w * 0.28, p.w * 0.28), p.y + 0.8, p.z + rand(-p.d * 0.28, p.d * 0.28))
        sc.set(rand(1.5, 3.2), rand(1, 2), rand(1.5, 3.4))
        m.compose(pv, q, sc)
        acMesh.setMatrixAt(n++, m)
      }
    }
    acMesh.count = n
    acMesh.instanceMatrix.needsUpdate = true
    this.group.add(acMesh)

    const antGeo = new THREE.CylinderGeometry(0.08, 0.12, 1, 5)
    const antMat = new THREE.MeshStandardMaterial({ color: 0x44464c, roughness: 0.7, metalness: 0.5 })
    const antMesh = new THREE.InstancedMesh(antGeo, antMat, props.length)
    let an = 0
    for (const p of props) {
      if (!chance(0.5)) continue
      pv.set(p.x, p.y + rand(3, 7), p.z)
      sc.set(1, rand(6, 14), 1)
      m.compose(pv, q, sc)
      antMesh.setMatrixAt(an++, m)
    }
    antMesh.count = an
    antMesh.instanceMatrix.needsUpdate = true
    this.group.add(antMesh)
  }

