import * as THREE from 'three'
import { pick, rand } from './utils.js'

const SKIN = [0xf0c8a0, 0xd9a878, 0xa9744c, 0x80573a, 0x5f3d28]
const SHIRTS = [0x2f4858, 0x7a2e3c, 0x3e5c3a, 0x4a3c66, 0x8a6a2f, 0x2c2c30, 0x24606b, 0xc9c3b4, 0x8f3f2a]
const PANTS = [0x252a33, 0x31343a, 0x3d342a, 0x203347, 0x4a4a50, 0x5a4b3a]
const HAIR = [0x1b1a19, 0x30241a, 0x5a3b22, 0x8c6a3f, 0x2a2a2a]

function mat(color, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.02, ...extra })
}

export function createHumanoid(opts = {}) {
  const skin = opts.skin ?? pick(SKIN)
  const shirt = opts.shirt ?? pick(SHIRTS)
  const pants = opts.pants ?? pick(PANTS)
  const hair = opts.hair ?? pick(HAIR)
  const isCop = opts.cop ?? false
  const group = new THREE.Group()
  const skinMat = mat(skin)
  const shirtMat = mat(isCop ? 0x232d3d : shirt)
  const pantsMat = mat(isCop ? 0x1b2230 : pants)
  const shoeMat = mat(0x17181c, { roughness: 0.6 })
  const hairMat = mat(hair)

  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.62, 0.27), shirtMat)
  torso.position.y = 1.24
  group.add(torso)

  if (isCop) {
    const vest = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.4, 0.29), mat(0x141a24, { roughness: 0.7 }))
    vest.position.y = 1.28
    group.add(vest)
    const badge = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.09, 0.02), mat(0xd6b45a, { metalness: 0.7, roughness: 0.3 }))
    badge.position.set(-0.15, 1.4, 0.145)
    group.add(badge)
  }

  const hips = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.2, 0.25), pantsMat)
  hips.position.y = 0.96
  group.add(hips)

  const head = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.28, 0.25), skinMat)
  head.position.y = 1.71
  group.add(head)
  const hairMesh = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.11, 0.27), hairMat)
  hairMesh.position.set(0, 1.86, -0.01)
  group.add(hairMesh)
  const nose = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.07, 0.06), skinMat)
  nose.position.set(0, 1.69, 0.15)
  group.add(nose)

  if (isCop) {
    const cap = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.09, 0.3), mat(0x11151d))
    cap.position.y = 1.9
    group.add(cap)
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.03, 0.14), mat(0x080a0f, { roughness: 0.5 }))
    brim.position.set(0, 1.87, 0.2)
    group.add(brim)
  }

  const legGeo = new THREE.BoxGeometry(0.17, 0.84, 0.21)
  const shoeGeo = new THREE.BoxGeometry(0.19, 0.12, 0.3)
  const armGeo = new THREE.BoxGeometry(0.125, 0.58, 0.16)
  const handGeo = new THREE.BoxGeometry(0.12, 0.12, 0.13)

  const leftLeg = new THREE.Group()
  leftLeg.position.set(-0.115, 0.92, 0)
  const lLegMesh = new THREE.Mesh(legGeo, pantsMat)
  lLegMesh.position.y = -0.42
  leftLeg.add(lLegMesh)
  const lShoe = new THREE.Mesh(shoeGeo, shoeMat)
  lShoe.position.set(0, -0.84, 0.04)
  leftLeg.add(lShoe)
  group.add(leftLeg)

  const rightLeg = new THREE.Group()
  rightLeg.position.set(0.115, 0.92, 0)
  const rLegMesh = new THREE.Mesh(legGeo, pantsMat)
  rLegMesh.position.y = -0.42
  rightLeg.add(rLegMesh)
  const rShoe = new THREE.Mesh(shoeGeo, shoeMat)
  rShoe.position.set(0, -0.84, 0.04)
  rightLeg.add(rShoe)
  group.add(rightLeg)

  const leftArm = new THREE.Group()
  leftArm.position.set(-0.3, 1.5, 0)
  const lArmMesh = new THREE.Mesh(armGeo, shirtMat)
  lArmMesh.position.y = -0.29
  leftArm.add(lArmMesh)
  const lHand = new THREE.Mesh(handGeo, skinMat)
  lHand.position.y = -0.62
  leftArm.add(lHand)
  group.add(leftArm)

  const rightArm = new THREE.Group()
  rightArm.position.set(0.3, 1.5, 0)
  const rArmMesh = new THREE.Mesh(armGeo, shirtMat)
  rArmMesh.position.y = -0.29
  rightArm.add(rArmMesh)
  const rHand = new THREE.Mesh(handGeo, skinMat)
  rHand.position.y = -0.62
  rightArm.add(rHand)
  group.add(rightArm)

  const gun = new THREE.Group()
  const gunBody = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.14, 0.3), mat(0x1b1c20, { metalness: 0.55, roughness: 0.35 }))
  gunBody.position.set(0, -0.68, 0.18)
  gun.add(gunBody)
  const gunGrip = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.14, 0.08), mat(0x2a2b30, { roughness: 0.6 }))
  gunGrip.position.set(0, -0.76, 0.06)
  gunGrip.rotation.x = 0.3
  gun.add(gunGrip)
  rightArm.add(gun)
  gun.visible = false

  group.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = true
      o.receiveShadow = false
    }
  })

  return {
    group,
    parts: { torso, head, leftLeg, rightLeg, leftArm, rightArm, gun, hips, hairMesh },
    materials: { skinMat, shirtMat, pantsMat, shoeMat, hairMat },
    phase: rand(0, Math.PI * 2),
    aiming: false,
    walk: 0
  }
}

export function animateHumanoid(rig, dt, moveSpeed = 0, aiming = false, extra = {}) {
  const p = rig.parts
  rig.walk += dt * (2.2 + moveSpeed * 1.5)
  const amp = Math.min(1, moveSpeed / 5) * 0.75
  const s = Math.sin(rig.walk)
  const c = Math.sin(rig.walk * 2)

  p.leftLeg.rotation.x = s * amp
  p.rightLeg.rotation.x = -s * amp
  p.torso.position.y = 1.24 + Math.abs(c) * 0.016 * amp
  p.head.rotation.z = Math.sin(rig.walk * 0.5) * 0.02

  if (aiming) {
    p.rightArm.rotation.x = -Math.PI / 2 + 0.05
    p.rightArm.rotation.z = 0.06
    p.leftArm.rotation.x = -Math.PI / 2 + 0.22
    p.leftArm.rotation.z = -0.25
    p.gun.visible = true
  } else {
    p.rightArm.rotation.x = -s * amp * 0.8
    p.leftArm.rotation.x = s * amp * 0.8
    p.rightArm.rotation.z = 0
    p.leftArm.rotation.z = 0
    p.gun.visible = false
  }
  if (extra.fall) {
    rig.group.rotation.x = -Math.PI / 2
    p.leftLeg.rotation.x = 0.2
    p.rightLeg.rotation.x = -0.1
    p.leftArm.rotation.x = 0.5
    p.rightArm.rotation.x = -0.6
  }
}

export function createCop(opts = {}) {
  return createHumanoid({ cop: true, shirt: 0x263247, pants: 0x1a2130, ...opts })
}

import * as THREE from 'three'
import { clamp, damp, dampAngle, rand, randInt, pick, chance, glowSprite, TAU } from './utils.js'

const BODY_COLORS = [
  0x9e2f2f, 0x284a72, 0xd9d4c7, 0x22242a, 0x5b6470, 0x2c5b4a,
  0xb07a2a, 0x6e2c55, 0x3b6f8a, 0xc25a2e, 0x8a8f96, 0x18222b
]

const SPECS = {
  sedan: { w: 2.0, l: 4.5, bodyH: 0.56, cabH: 0.5, cabL: 0.44, max: 30, accel: 11, mass: 1 },
  sports: { w: 2.06, l: 4.3, bodyH: 0.5, cabH: 0.42, cabL: 0.36, max: 38, accel: 15, mass: 0.9 },
  suv: { w: 2.16, l: 4.95, bodyH: 0.72, cabH: 0.55, cabL: 0.46, max: 26, accel: 9, mass: 1.35 },
  van: { w: 2.24, l: 5.4, bodyH: 0.85, cabH: 0.7, cabL: 0.52, max: 23, accel: 8, mass: 1.5 },
  police: { w: 2.04, l: 4.6, bodyH: 0.58, cabH: 0.5, cabL: 0.44, max: 34, accel: 13, mass: 1.1 },
  taxi: { w: 2.0, l: 4.5, bodyH: 0.56, cabH: 0.5, cabL: 0.44, max: 29, accel: 10.5, mass: 1 }
}

function makeWheel(radius = 0.37) {
  const g = new THREE.Group()
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x15161a, roughness: 0.9 })
  const tire = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 0.28, 12), tireMat)
  tire.rotation.z = Math.PI / 2
  tire.castShadow = true
  g.add(tire)
  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(radius * 0.55, radius * 0.55, 0.3, 8),
    new THREE.MeshStandardMaterial({ color: 0x8d9298, metalness: 0.75, roughness: 0.3 })
  )
  rim.rotation.z = Math.PI / 2
  g.add(rim)
  const spoke = new THREE.Mesh(
    new THREE.BoxGeometry(0.31, radius * 1.05, 0.09),
    new THREE.MeshStandardMaterial({ color: 0x6d7278, metalness: 0.7, roughness: 0.35 })
  )
  g.add(spoke)
  return g
}

export function createCarMesh(type = 'sedan', color = 0x9e2f2f) {
  const spec = SPECS[type] || SPECS.sedan
  const { w, l, bodyH, cabH, cabL } = spec
  const group = new THREE.Group()
  const car = { group, wheels: [], frontWheels: [], headMats: [], tailMats: [], type, spec }

  const paint = new THREE.MeshStandardMaterial({ color, roughness: 0.32, metalness: 0.55 })
  const dark = new THREE.MeshStandardMaterial({ color: 0x1a1c20, roughness: 0.45, metalness: 0.35 })
  const glass = new THREE.MeshStandardMaterial({ color: 0x0e1a24, roughness: 0.08, metalness: 0.75, transparent: true, opacity: 0.92 })
  const trim = new THREE.MeshStandardMaterial({ color: 0x0d0e11, roughness: 0.7 })

  const bodyY = 0.42 + bodyH / 2
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, bodyH, l), paint)
  body.position.y = bodyY
  body.castShadow = true
  body.receiveShadow = true
  group.add(body)
  car.body = body

  // Slight nose and tail shaping.
  const nose = new THREE.Mesh(new THREE.BoxGeometry(w * 0.94, bodyH * 0.6, 0.35), paint)
  nose.position.set(0, bodyY - 0.08, l / 2 - 0.05)
  nose.castShadow = true
  group.add(nose)
  const tail = new THREE.Mesh(new THREE.BoxGeometry(w * 0.94, bodyH * 0.6, 0.3), paint)
  tail.position.set(0, bodyY - 0.06, -l / 2 + 0.02)
  group.add(tail)

  const cabin = new THREE.Mesh(new THREE.BoxGeometry(w * 0.84, cabH, l * cabL), glass)
  cabin.position.set(0, bodyY + bodyH / 2 + cabH / 2 - 0.02, -l * 0.04)
  cabin.castShadow = true
  group.add(cabin)
  const roof = new THREE.Mesh(new THREE.BoxGeometry(w * 0.8, 0.08, l * cabL * 0.82), paint)
  roof.position.set(0, bodyY + bodyH / 2 + cabH - 0.01, -l * 0.04)
  roof.castShadow = true
  group.add(roof)
  const pillarL = new THREE.Mesh(new THREE.BoxGeometry(0.07, cabH, 0.1), paint)
  pillarL.position.set(-w * 0.41, bodyY + bodyH / 2 + cabH / 2, -l * cabL * 0.5)
  group.add(pillarL)
  const pillarR = pillarL.clone()
  pillarR.position.x = w * 0.41
  group.add(pillarR)

  const bumperF = new THREE.Mesh(new THREE.BoxGeometry(w * 0.98, 0.16, 0.18), trim)
  bumperF.position.set(0, 0.4, l / 2 + 0.04)
  group.add(bumperF)
  const bumperB = bumperF.clone()
  bumperB.position.z = -l / 2 - 0.03
  group.add(bumperB)

  // Lights
  const headMat = new THREE.MeshStandardMaterial({ color: 0xfff2cf, emissive: 0xffe2a8, emissiveIntensity: 1.2, toneMapped: false })
  const tailMat = new THREE.MeshStandardMaterial({ color: 0xff3524, emissive: 0xff1a0a, emissiveIntensity: 1.6, toneMapped: false })
  for (const sx of [-0.32, 0.32]) {
    const h = new THREE.Mesh(new THREE.BoxGeometry(w * 0.24, 0.13, 0.06), headMat)
    h.position.set(sx * w, bodyY + 0.06, l / 2 + 0.1)
    group.add(h)
    const t = new THREE.Mesh(new THREE.BoxGeometry(w * 0.26, 0.12, 0.06), tailMat)
    t.position.set(sx * w, bodyY + 0.06, -l / 2 - 0.07)
    group.add(t)
  }
  car.headMats.push(headMat)
  car.tailMats.push(tailMat)

  // Headlight cones for atmosphere at night.
  const coneMat = new THREE.MeshBasicMaterial({ color: 0xffe6b0, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, toneMapped: false })
  for (const sx of [-0.34, 0.34]) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry(2.0, 10, 12, 1, true), coneMat)
    cone.rotation.x = Math.PI / 2
    cone.position.set(sx * w, 0.55, l / 2 + 5)
    group.add(cone)
  }
  car.coneMat = coneMat

  // Wheels
  const wheelGeoRadius = type === 'suv' || type === 'van' ? 0.43 : 0.37
  const wx = w / 2 - 0.08
  const wz = l * 0.31
  const wheelPositions = [
    [-wx, wheelGeoRadius, wz, true],
    [wx, wheelGeoRadius, wz, true],
    [-wx, wheelGeoRadius, -wz, false],
    [wx, wheelGeoRadius, -wz, false]
  ]
  for (const [x, y, z, front] of wheelPositions) {
    const wg = makeWheel(wheelGeoRadius)
    wg.position.set(x, y, z)
    group.add(wg)
    car.wheels.push(wg)
    if (front) car.frontWheels.push(wg)
  }

  if (type === 'sports') {
    const spoiler = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, 0.06, 0.32), trim)
    spoiler.position.set(0, bodyY + bodyH / 2 + 0.3, -l / 2 + 0.34)
    group.add(spoiler)
    for (const sx of [-0.36, 0.36]) {
      const stand = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.24, 0.12), trim)
      stand.position.set(sx * w, bodyY + bodyH / 2 + 0.16, -l / 2 + 0.34)
      group.add(stand)
    }
  }

  if (type === 'taxi') {
    const sign = new THREE.Mesh(
      new THREE.BoxGeometry(0.8, 0.24, 0.32),
      new THREE.MeshStandardMaterial({ color: 0xffe28a, emissive: 0xffb300, emissiveIntensity: 1.4, toneMapped: false })
    )
    sign.position.set(0, bodyY + bodyH / 2 + cabH + 0.14, -l * 0.04)
    group.add(sign)
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(w * 1.005, 0.12, l * 0.6), new THREE.MeshStandardMaterial({ color: 0x1c1c1c, roughness: 0.5 }))
    stripe.position.set(0, bodyY - 0.02, 0)
    group.add(stripe)
  }

  if (type === 'police') {
    const white = new THREE.MeshStandardMaterial({ color: 0xe8e9ea, roughness: 0.4, metalness: 0.2 })
    for (const sx of [-1, 1]) {
      const door = new THREE.Mesh(new THREE.BoxGeometry(0.05, bodyH * 0.78, l * 0.42), white)
      door.position.set(sx * (w / 2 + 0.01), bodyY, 0.1)
      group.add(door)
    }
    const barBase = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.08, 0.28), dark)
    barBase.position.set(0, bodyY + bodyH / 2 + cabH + 0.06, -0.2)
    group.add(barBase)
    car.redMat = new THREE.MeshStandardMaterial({ color: 0xff2b2b, emissive: 0xff1010, emissiveIntensity: 2, toneMapped: false })
    car.blueMat = new THREE.MeshStandardMaterial({ color: 0x2b6bff, emissive: 0x1040ff, emissiveIntensity: 2, toneMapped: false })
    const red = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.16, 0.24), car.redMat)
    red.position.set(-0.26, bodyY + bodyH / 2 + cabH + 0.15, -0.2)
    group.add(red)
    const blue = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.16, 0.24), car.blueMat)
    blue.position.set(0.26, bodyY + bodyH / 2 + cabH + 0.15, -0.2)
    group.add(blue)
    car.redGlow = glowSprite(0xff2020, 3.2, 0.0)
    car.redGlow.position.set(-0.26, bodyY + bodyH / 2 + cabH + 0.3, -0.2)
    group.add(car.redGlow)
    car.blueGlow = glowSprite(0x3060ff, 3.2, 0.0)
    car.blueGlow.position.set(0.26, bodyY + bodyH / 2 + cabH + 0.3, -0.2)
    group.add(car.blueGlow)
  }

  group.traverse((o) => { if (o.isMesh) o.castShadow = true })
  return car
}

export class Vehicle {
  constructor(game, { type = 'sedan', x = 0, z = 0, heading = 0, color = pick(BODY_COLORS), police = false, traffic = false } = {}) {
    this.game = game
    this.type = police ? 'police' : type
    this.meshData = createCarMesh(this.type, police ? 0x22252b : color)
    this.mesh = this.meshData.group
    this.mesh.position.set(x, 0, z)
    this.heading = heading
    this.mesh.rotation.y = heading
    this.pos = new THREE.Vector3(x, 0, z)
    this.vel = new THREE.Vector2(0, 0)
    this.speed = 0
    this.steer = 0
    this.health = 100
    this.maxHealth = 100
    this.spec = this.meshData.spec
    this.police = police
    this.traffic = traffic
    this.driver = null
    this.occupiedByPlayer = false
    this.destroyed = false
    this.burnTimer = 0
    this.lightPhase = rand(0, TAU)
    this.coneMat = this.meshData.coneMat
    this.wheels = this.meshData.wheels
    this.frontWheels = this.meshData.frontWheels
    this.headMats = this.meshData.headMats
    this.tailMats = this.meshData.tailMats
    this.radius = 1.9
    this.mesh.userData.vehicle = this
    this.mesh.traverse((o) => { o.userData.vehicle = this })

    this.trafficPath = null
    if (traffic) this._initTrafficPath()

    game.scene.add(this.mesh)
  }

  get forward() {
    return new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading))
  }

  get speedKmh() {
    return Math.abs(this.speed) * 3.6
  }

  _initTrafficPath() {
    let si = randInt(-4, 4)
    let sj = randInt(-4, 4)
    const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]]
    const dir = pick(dirs)
    this.trafficPath = { si, sj, ei: si + dir[0], ej: sj + dir[1], dir }
    if (Math.abs(this.trafficPath.ei) > 5 || Math.abs(this.trafficPath.ej) > 5) {
      this.trafficPath.ei = si
      this.trafficPath.ej = sj
      this.trafficPath.dir = [0, 0]
    }
    const right = new THREE.Vector2(-this.trafficPath.dir[1], this.trafficPath.dir[0]).multiplyScalar(3.5)
    const sx = this.trafficPath.si * 70
    const sz = this.trafficPath.sj * 70
    this.pos.set(sx + right.x, 0, sz + right.y)
    this.heading = Math.atan2(this.trafficPath.dir[0], this.trafficPath.dir[1])
    this.mesh.position.copy(this.pos)
    this.mesh.rotation.y = this.heading
    this._nextTrafficTarget()
  }

  _nextTrafficTarget() {
    const p = this.trafficPath
    const ex = p.ei * 70
    const ez = p.ej * 70
    const right = new THREE.Vector2(-p.dir[1], p.dir[0]).multiplyScalar(3.5)
    this.trafficTarget = new THREE.Vector2(ex + right.x, ez + right.y)
    this.trafficNode = { i: p.ei, j: p.ej }
    this.cruise = rand(9, 14)
  }

  _advanceTrafficPath() {
    const p = this.trafficPath
    const opts = []
    const straight = [p.dir[0], p.dir[1]]
    const left = [-p.dir[1], p.dir[0]]
    const rightTurn = [p.dir[1], -p.dir[0]]
    const add = (d, w) => {
      const ni = p.ei + d[0]
      const nj = p.ej + d[1]
      if (ni < -5 || ni > 5 || nj < -5 || nj > 5) return
      opts.push({ d, w })
    }
    add(straight, 0.56)
    add(left, 0.19)
    add(rightTurn, 0.19)
    if (opts.length === 0) {
      add([-p.dir[0], -p.dir[1]], 1)
      opts.push({ d: [-p.dir[0], -p.dir[1]], w: 0.1 })
    }
    let total = 0
    for (const o of opts) total += o.w
    let r = Math.random() * total
    let chosen = opts[0].d
    for (const o of opts) { r -= o.w; if (r <= 0) { chosen = o.d; break } }
    this.trafficPath = { si: p.ei, sj: p.ej, ei: p.ei + chosen[0], ej: p.ej + chosen[1], dir: chosen }
    this._nextTrafficTarget()
  }

  updateTraffic(dt, game) {
    if (this.destroyed) { this._integrate(dt, game); return }
    if (!this.trafficTarget) return
    const to = new THREE.Vector2(this.trafficTarget.x - this.pos.x, this.trafficTarget.y - this.pos.z)
    const dist = to.length()
    if (dist < 2.2) {
      this.trafficPath.si = this.trafficPath.ei
      this.trafficPath.sj = this.trafficPath.ej
      this._advanceTrafficPath()
      const t2 = new THREE.Vector2(this.trafficTarget.x - this.pos.x, this.trafficTarget.y - this.pos.z)
      if (t2.length() < 1) return
      this.heading = dampAngle(this.heading, Math.atan2(t2.x, t2.y), 3, dt)
    } else {
      const desired = Math.atan2(to.x, to.y)
      this.heading = dampAngle(this.heading, desired, 3.5, dt)
    }

    // Brake for whatever is ahead.
    let targetSpeed = this.cruise
    const fwd = this.forward
    const ahead = 11
    const ax = this.pos.x + fwd.x * ahead
    const az = this.pos.z + fwd.y * ahead
    if (game.playerCar && game.playerCar !== this) {
      const d = Math.hypot(game.playerCar.pos.x - ax, game.playerCar.pos.z - az)
      if (d < 5) targetSpeed = 0
    }
    for (const v of game.vehicles) {
      if (v === this) continue
      const dx = v.pos.x - this.pos.x
      const dz = v.pos.z - this.pos.z
      const dd = Math.hypot(dx, dz)
      if (dd > 13) continue
      if (dx * fwd.x + dz * fwd.y > 3) targetSpeed = Math.min(targetSpeed, Math.max(0, (dd - 4) * 2.2))
    }
    if (game.player && !game.player.car) {
      const dx = game.player.pos.x - this.pos.x
      const dz = game.player.pos.z - this.pos.z
      if (Math.hypot(dx, dz) < 9 && dx * fwd.x + dz * fwd.y > 0) targetSpeed = Math.min(targetSpeed, 2)
    }

    this.speed = damp(this.speed, targetSpeed, 2.6, dt)
    this.vel.set(fwd.x * this.speed, fwd.y * this.speed)
    this._integrate(dt, game)
  }

  updatePolice(dt, game) {
    if (this.destroyed) { this._integrate(dt, game); return }
    const target = game.player.car ? game.player.car.pos : game.player.pos
    const dx = target.x - this.pos.x
    const dz = target.z - this.pos.z
    const dist = Math.hypot(dx, dz)
    const desired = Math.atan2(dx, dz)
    this.heading = dampAngle(this.heading, desired, dist < 30 ? 2.2 : 1.5, dt)
    let targetSpeed = dist > 12 ? this.spec.max * (dist > 90 ? 0.8 : 0.62) : 8
    // Back off a little so they circle instead of grinding.
    if (dist < 6) targetSpeed = 4
    this.speed = damp(this.speed, targetSpeed, 1.5, dt)
    const fwd = this.forward
    this.vel.set(fwd.x * this.speed, fwd.y * this.speed)
    this._integrate(dt, game)

    this.lightPhase += dt * 7
    if (this.meshData.redMat) {
      const on = Math.sin(this.lightPhase) > 0
      this.meshData.redMat.emissiveIntensity = on ? 3.4 : 0.35
      this.meshData.blueMat.emissiveIntensity = on ? 0.35 : 3.4
      if (this.meshData.redGlow) this.meshData.redGlow.material.opacity = on ? 0.8 : 0.04
      if (this.meshData.blueGlow) this.meshData.blueGlow.material.opacity = on ? 0.04 : 0.8
    }
  }

  updatePlayerDriven(dt, input) {
    if (this.destroyed) return
    const throttle = (input.down('KeyW') || input.down('ArrowUp') ? 1 : 0) + (input.down('KeyS') || input.down('ArrowDown') ? -1 : 0)
    const steerIn = (input.down('KeyA') || input.down('ArrowLeft') ? 1 : 0) - (input.down('KeyD') || input.down('ArrowRight') ? 1 : 0)
    const handbrake = input.down('Space')
    const fwd = this.forward
    let forwardSpeed = this.vel.x * fwd.x + this.vel.y * fwd.y
    const lateral = new THREE.Vector2(this.vel.x - fwd.x * forwardSpeed, this.vel.y - fwd.y * forwardSpeed)

    const max = this.spec.max
    const accel = this.spec.accel
    if (throttle > 0) {
      if (forwardSpeed < -0.5) forwardSpeed += 18 * dt
      else forwardSpeed += accel * dt
    } else if (throttle < 0) {
      if (forwardSpeed > 0.5) forwardSpeed -= 20 * dt
      else forwardSpeed -= accel * 0.65 * dt
    } else {
      forwardSpeed *= Math.exp(-0.7 * dt)
    }
    if (handbrake) forwardSpeed *= Math.exp(-1.6 * dt)
    forwardSpeed = clamp(forwardSpeed, -9, max)

    const speedT = clamp(Math.abs(forwardSpeed) / 8, 0, 1)
    const turn = (1.9 - clamp(Math.abs(forwardSpeed) / max, 0, 1) * 0.9) * speedT
    this.heading += steerIn * turn * dt * (forwardSpeed >= -0.2 ? 1 : -1)
    this.steer = damp(this.steer, steerIn, 8, dt)

    const newFwd = this.forward
    const grip = handbrake ? 0.9 : 7.5
    lateral.multiplyScalar(Math.exp(-grip * dt))
    this.vel.set(newFwd.x * forwardSpeed + lateral.x, newFwd.y * forwardSpeed + lateral.y)
    this.speed = forwardSpeed
    this._integrate(dt, this.game)
    if (handbrake && Math.abs(forwardSpeed) > 8) {
      if (Math.random() < 0.35) this.game.effects.smoke(this.pos.x + newFwd.x * -2, 0.15, this.pos.z + newFwd.y * -2, 0.5)
    }
  }

  updateCoast(dt, game) {
    if (this.destroyed) { this._integrate(dt, game); return }
    this.speed *= Math.exp(-1.3 * dt)
    const f = this.forward
    this.vel.set(f.x * this.speed, f.y * this.speed)
    this._integrate(dt, game)
  }

  _integrate(dt, game) {
    const oldX = this.pos.x
    const oldZ = this.pos.z
    this.pos.x += this.vel.x * dt
    this.pos.z += this.vel.y * dt

    // Buildings: two collision discs along the chassis.
    const f = this.forward
    const offsets = [1.35, -1.35]
    const before = { x: this.pos.x, z: this.pos.z }
    for (const off of offsets) {
      const p = { x: this.pos.x + f.x * off, z: this.pos.z + f.y * off }
      game.world.resolveCircle(p, 1.15)
      const dx = p.x - (this.pos.x + f.x * off)
      const dz = p.z - (this.pos.z + f.y * off)
      this.pos.x += dx * 0.8
      this.pos.z += dz * 0.8
    }
    const hitDx = this.pos.x - before.x
    const hitDz = this.pos.z - before.z
    if (hitDx * hitDx + hitDz * hitDz > 0.0004) {
      const n = new THREE.Vector2(hitDx, hitDz).normalize()
      const vn = this.vel.dot(n)
      if (vn < 0) {
        this.vel.addScaledVector(n, -vn * 1.4)
        const impact = Math.abs(vn)
        if (impact > 3.5) {
          this.health -= impact * 1.7
          this.game.effects.sparks(this.pos.x, 0.7, this.pos.z, 8)
          if (impact > 7) this.game.audio.thud()
        }
      }
      this.speed *= 0.72
    }

    this.mesh.position.set(this.pos.x, 0, this.pos.z)
    this.mesh.rotation.y = this.heading
    for (const w of this.frontWheels) w.rotation.y = this.steer * 0.5
    const spin = this.speed * dt / 0.37
    for (const w of this.wheels) {
      for (const child of w.children) child.rotation.x += spin
    }

    if (this.health < 38 && !this.destroyed) {
      this.burnTimer -= dt
      if (this.burnTimer <= 0) {
        this.burnTimer = 0.08
        game.effects.smoke(this.pos.x, 0.8, this.pos.z, this.health < 18 ? 1.5 : 0.7)
        if (this.health < 18 && Math.random() < 0.3) game.effects.fire(this.pos.x, 0.9, this.pos.z, 0.8)
      }
    }
    if (this.health <= 0 && !this.destroyed) game.explodeVehicle(this)

    const distMoved = Math.hypot(this.pos.x - oldX, this.pos.z - oldZ)
    if (distMoved > 0.001) {
      // Run over pedestrians.
      const checkR = this.radius + 0.4
      for (const ped of game.peds) {
        if (ped.dead) continue
        const dx = ped.pos.x - this.pos.x
        const dz = ped.pos.z - this.pos.z
        if (dx * dx + dz * dz < checkR * checkR && Math.abs(this.speed) > 5 && ped.vehicleCooldown <= 0) {
          ped.vehicleCooldown = 2
          game.runOver(this, ped)
        }
      }
      for (const cop of game.cops) {
        if (cop.dead) continue
        const dx = cop.pos.x - this.pos.x
        const dz = cop.pos.z - this.pos.z
        if (dx * dx + dz * dz < checkR * checkR && Math.abs(this.speed) > 5 && cop.vehicleCooldown <= 0) {
          cop.vehicleCooldown = 2
          game.runOver(this, cop)
        }
      }
    }
  }

  applyDamage(amount, game) {
    if (this.destroyed) return
    this.health -= amount
    if (this.health <= 0 && !this.destroyed) game.explodeVehicle(this)
  }

  addDriverVisual(driver) {
    this.driver = driver
  }

  dispose() {
    this.game.scene.remove(this.mesh)
  }
}

import * as THREE from 'three'
import { clamp, damp, dampAngle, rand, randInt, pick, chance, TAU, dist2 } from './utils.js'
import { createHumanoid, animateHumanoid, createCop } from './character.js'
import { GRID } from './world.js'

const PED_SHIRTS = [0xc94f4f, 0x4f7ac9, 0x4fc97a, 0xc9a94f, 0x8a4fc9, 0x4fc9c9, 0xd8d2c4, 0x32343a, 0xd77a3a, 0x5a6b45]
const PED_PANTS = [0x2c2f36, 0x3b342c, 0x23303f, 0x4a4a50, 0x6b5a41, 0x1e1f23]

export class Ped {
  constructor(game, x, z, opts = {}) {
    this.game = game
    this.rig = createHumanoid({
      shirt: pick(PED_SHIRTS),
      pants: pick(PED_PANTS),
      ...opts.look
    })
    this.group = this.rig.group
    this.pos = new THREE.Vector3(x, 0.15, z)
    this.group.position.copy(this.pos)
    this.heading = rand(0, TAU)
    this.group.rotation.y = this.heading
    this.group.traverse((o) => { o.userData.ped = this })
    this.state = 'walk'
    this.health = 30
    this.dead = false
    this.deadTimer = 0
    this.speed = rand(1.1, 1.8)
    this.waitTimer = rand(0, 2)
    this.fleeTimer = 0
    this.threat = new THREE.Vector3()
    this.target = new THREE.Vector2()
    this.targetTimer = 0
    this.vehicleCooldown = 0
    this.blood = null
    this.block = opts.block || { i: randInt(-5, 4), j: randInt(-5, 4) }
    this._pickTarget()
    this.group.position.y = 0.15
    game.scene.add(this.group)
  }

  _pickTarget() {
    const c = this.block
    const cx = GRID * c.i + GRID / 2
    const cz = GRID * c.j + GRID / 2
    const off = 24.6
    const side = randInt(0, 3)
    const t = rand(-23, 23)
    if (side === 0) this.target.set(cx + t, cz - off)
    else if (side === 1) this.target.set(cx + t, cz + off)
    else if (side === 2) this.target.set(cx - off, cz + t)
    else this.target.set(cx + off, cz + t)
    // Don't route into the sea.
    if (this.target.y > 348) this.target.y = 348
    this.targetTimer = 0
  }

  scare(source, radius = 18) {
    if (this.dead) return
    const d = Math.hypot(this.pos.x - source.x, this.pos.z - source.z)
    if (d > radius) return
    this.state = 'flee'
    this.fleeTimer = rand(4, 7)
    this.threat.set(source.x, 0, source.z)
    const dx = this.pos.x - source.x
    const dz = this.pos.z - source.z
    const len = Math.hypot(dx, dz) || 1
    this.target.set(this.pos.x + (dx / len) * 18 + rand(-5, 5), this.pos.z + (dz / len) * 18 + rand(-5, 5))
  }

  update(dt, game) {
    this.vehicleCooldown = Math.max(0, this.vehicleCooldown - dt)
    if (this.dead) {
      this.deadTimer += dt
      if (this.deadTimer > 22) {
        this.game.scene.remove(this.group)
        if (this.blood) this.game.scene.remove(this.blood)
        this.removed = true
      }
      return
    }
    const playerDist = Math.hypot(this.pos.x - game.player.pos.x, this.pos.z - game.player.pos.z)
    if (this.state === 'flee') {
      this.fleeTimer -= dt
      if (this.fleeTimer <= 0) {
        this.state = 'walk'
        this._pickTarget()
      } else {
        // keep running away in a straight-ish line, with small jitter
        this.speed = 5.2
        const tx = this.target.x
        const tz = this.target.y
        const dx = tx - this.pos.x
        const dz = tz - this.pos.z
        if (Math.hypot(dx, dz) < 2) {
          const ax = this.pos.x - this.threat.x
          const az = this.pos.z - this.threat.z
          const len = Math.hypot(ax, az) || 1
          this.target.set(this.pos.x + (ax / len) * 20 + rand(-6, 6), this.pos.z + (az / len) * 20 + rand(-6, 6))
        }
      }
    } else {
      this.speed = damp(this.speed, this.waitTimer > 0 ? 0 : rand(1.2, 1.7), 3, dt)
      if (this.waitTimer > 0) {
        this.waitTimer -= dt
      } else {
        const d = Math.hypot(this.target.x - this.pos.x, this.target.y - this.pos.z)
        if (d < 1.2) {
          this.waitTimer = rand(0, 2.2)
          this._pickTarget()
        }
      }
    }

    const dx = this.target.x - this.pos.x
    const dz = this.target.y - this.pos.z
    const dist = Math.hypot(dx, dz)
    if (dist > 0.6) {
      const desired = Math.atan2(dx, dz)
      this.heading = dampAngle(this.heading, desired, 8, dt)
      this.pos.x += (dx / dist) * this.speed * dt
      this.pos.z += (dz / dist) * this.speed * dt
      this.group.rotation.y = this.heading
    }

    // Avoid the player's body.
    if (playerDist < 0.9 && !game.player.car) {
      const ax = this.pos.x - game.player.pos.x
      const az = this.pos.z - game.player.pos.z
      const l = Math.hypot(ax, az) || 1
      this.pos.x += (ax / l) * 1.2 * dt
      this.pos.z += (az / l) * 1.2 * dt
    }
    if (game.player.car && this.state !== 'flee') {
      const c = game.player.car
      const d = Math.hypot(this.pos.x - c.pos.x, this.pos.z - c.pos.z)
      if (d < 14 && Math.abs(c.speed) > 6) this.scare(c.pos, 14)
    }

    game.world.resolveCircle(this.pos, 0.36)
    this.group.position.set(this.pos.x, 0.15, this.pos.z)
    animateHumanoid(this.rig, dt, this.speed, false, { fall: false })
  }

  hit(damage, from, game) {
    if (this.dead) return
    this.health -= damage
    if (Math.random() < 0.6) this.scare(from, 60)
    if (this.health <= 0) this.kill(game)
  }

  kill(game, opts = {}) {
    if (this.dead) return
    this.dead = true
    this.state = 'dead'
    this.deadTimer = 0
    this.group.rotation.z = Math.PI / 2
    this.group.rotation.x = rand(-0.3, 0.3)
    this.group.position.y = 0.32
    this.group.rotation.y = this.heading + rand(-0.4, 0.4)
    const blood = new THREE.Mesh(
      new THREE.CircleGeometry(rand(0.5, 0.9), 12),
      new THREE.MeshBasicMaterial({ color: 0x521111, transparent: true, opacity: 0.75, depthWrite: false })
    )
    blood.rotation.x = -Math.PI / 2
    blood.position.set(this.pos.x, 0.02, this.pos.z)
    game.scene.add(blood)
    this.blood = blood
    if (!opts.silent) game.onPedKilled(this, opts)
  }
}

export class Cop {
  constructor(game, x, z) {
    this.game = game
    this.rig = createCop()
    this.group = this.rig.group
    this.pos = new THREE.Vector3(x, 0.15, z)
    this.group.position.copy(this.pos)
    this.heading = rand(0, TAU)
    this.health = 75
    this.dead = false
    this.deadTimer = 0
    this.speed = 0
    this.fireTimer = rand(0.8, 2)
    this.vehicleCooldown = 0
    this.rush = false
    this.group.traverse((o) => { o.userData.cop = this })
    game.scene.add(this.group)
  }

  update(dt, game) {
    this.vehicleCooldown = Math.max(0, this.vehicleCooldown - dt)
    if (this.dead) {
      this.deadTimer += dt
      if (this.deadTimer > 22) {
        game.scene.remove(this.group)
        this.removed = true
      }
      return
    }
    const target = game.player.car ? game.player.car.pos : game.player.pos
    const dx = target.x - this.pos.x
    const dz = target.z - this.pos.z
    const dist = Math.hypot(dx, dz)
    const desired = Math.atan2(dx, dz)
    this.heading = dampAngle(this.heading, desired, 7, dt)
    const want = dist > 16 ? 5.6 : dist > 9 ? 2.2 : 0.5
    this.speed = damp(this.speed, want, 5, dt)
    if (dist > 1.2) {
      this.pos.x += Math.sin(this.heading) * this.speed * dt
      this.pos.z += Math.cos(this.heading) * this.speed * dt
    }
    game.world.resolveCircle(this.pos, 0.38)
    this.group.position.set(this.pos.x, 0.15, this.pos.z)
    this.group.rotation.y = this.heading
    animateHumanoid(this.rig, dt, this.speed, true, {})
    this.rig.parts.gun.visible = true

    this.fireTimer -= dt
    if (this.fireTimer <= 0 && dist < 34 && !game.world.lineBlocked(this.pos.x, this.pos.z, target.x, target.z)) {
      this.fireTimer = rand(1.1, 2.0)
      game.copShoot(this)
    }
  }

  hit(damage, from, game) {
    if (this.dead) return
    this.health -= damage
    if (this.health <= 0) this.kill(game)
  }

  kill(game) {
    if (this.dead) return
    this.dead = true
    this.deadTimer = 0
    this.group.rotation.z = Math.PI / 2
    this.group.rotation.x = rand(-0.3, 0.3)
    this.group.position.y = 0.32
    game.onCopKilled(this)
  }
}

export function spawnInitialPeds(game, count = 34) {
  for (let i = 0; i < count; i++) {
    // Keep the initial spawn near the player so the city feels alive immediately.
    let block
    if (i < 16) {
      block = { i: randInt(-2, 2), j: randInt(-1, 2) }
    }
    const c = { x: GRID * block.i + GRID / 2, z: GRID * block.j + GRID / 2 }
    const off = 24.6
    const side = randInt(0, 3)
    const t = rand(-23, 23)
    let x
    let z
    if (side === 0) { x = c.x + t; z = c.z - off }
    else if (side === 1) { x = c.x + t; z = c.z + off }
    else if (side === 2) { x = c.x - off; z = c.z + t }
    else { x = c.x + off; z = c.z + t }
    game.peds.push(new Ped(game, x, z, { block }))
  }
}

