import * as THREE from 'three'
import { rand, clamp, glowTexture } from './utils.js'

class ParticlePool {
  constructor(scene, max, blending, opacityScale = 1) {
    this.max = max
    this.particles = []
    this.geo = new THREE.BufferGeometry()
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage))
    this.geo.setAttribute('pcolor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage))
    this.geo.setAttribute('psize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage))
    this.geo.setAttribute('palpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage))
    this.mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: glowTexture() }, opacityScale: { value: opacityScale } },
      vertexShader: /* glsl */`
        attribute vec3 pcolor;
        attribute float psize;
        attribute float palpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = pcolor;
          vAlpha = palpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = psize * (330.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: /* glsl */`
        uniform sampler2D map;
        uniform float opacityScale;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 t = texture2D(map, gl_PointCoord);
          gl_FragColor = vec4(vColor, t.a * vAlpha * opacityScale);
          if (gl_FragColor.a < 0.01) discard;
        }`,
      transparent: true,
      depthWrite: false,
      blending
    })
    this.points = new THREE.Points(this.geo, this.mat)
    this.points.frustumCulled = false
    this.points.renderOrder = 5
    scene.add(this.points)
    for (let i = 0; i < max; i++) this.particles.push({ alive: false })
    this.cursor = 0
  }

  emit(x, y, z, vx, vy, vz, life, size, color, gravity = 0, drag = 0, grow = 0, alpha = 1) {
    let p
    for (let i = 0; i < this.max; i++) {
      const idx = (this.cursor + i) % this.max
      if (!this.particles[idx].alive) { p = this.particles[idx]; this.cursor = (idx + 1) % this.max; break }
    }
    if (!p) { p = this.particles[this.cursor]; this.cursor = (this.cursor + 1) % this.max }
    p.alive = true
    p.x = x; p.y = y; p.z = z
    p.vx = vx; p.vy = vy; p.vz = vz
    p.life = life; p.maxLife = life
    p.size = size; p.color = color
    p.gravity = gravity; p.drag = drag; p.grow = grow
    p.alpha = alpha
  }

  update(dt) {
    let n = 0
    for (let i = 0; i < this.max; i++) {
      const p = this.particles[i]
      if (!p.alive) {
        this.alphas[i] = 0
        this.sizes[i] = 0
        continue
      }
      p.life -= dt
      if (p.life <= 0) {
        p.alive = false
        this.alphas[i] = 0
        this.sizes[i] = 0
        continue
      }
      const drag = Math.exp(-p.drag * dt)
      p.vx *= drag
      p.vz *= drag
      p.vy = p.vy * drag - p.gravity * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      if (p.y < 0.04) { p.y = 0.04; p.vy = Math.abs(p.vy) * 0.25 }
      const t = p.life / p.maxLife
      this.positions[n * 3] = p.x
      this.positions[n * 3 + 1] = p.y
      this.positions[n * 3 + 2] = p.z
      this.colors[n * 3] = p.color.r
      this.colors[n * 3 + 1] = p.color.g
      this.colors[n * 3 + 2] = p.color.b
      this.sizes[n] = Math.max(0.01, p.size + p.grow * (1 - t))
      this.alphas[n] = Math.min(1, t * 1.7) * p.alpha
      n++
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.pcolor.needsUpdate = true
    this.geo.attributes.psize.needsUpdate = true
    this.geo.attributes.palpha.needsUpdate = true
    this.geo.setDrawRange(0, this.max)
  }
}

const tempColor = new THREE.Color()

export class Effects {
  constructor(scene) {
    this.scene = scene
    this.glow = new ParticlePool(scene, 700, THREE.AdditiveBlending, 1)
    this.smokePool = new ParticlePool(scene, 420, THREE.NormalBlending, 0.55)
    this.shake = 0
    this.flashes = []
    for (let i = 0; i < 5; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture(), color: 0xffd08a, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false
      }))
      s.scale.set(2, 2, 1)
      scene.add(s)
      this.flashes.push({ sprite: s, life: 0, maxLife: 0.07, size: 2 })
    }
    this.flashCursor = 0

    const maxTracers = 40
    this.tracerPos = new Float32Array(maxTracers * 6)
    this.tracerCol = new Float32Array(maxTracers * 6)
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.tracerPos, 3).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('color', new THREE.BufferAttribute(this.tracerCol, 3).setUsage(THREE.DynamicDrawUsage))
    this.tracerMesh = new THREE.LineSegments(geo, new THREE.LineBasicMaterial({
      vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false
    }))
    this.tracerMesh.frustumCulled = false
    scene.add(this.tracerMesh)
    this.tracers = []

    this.explosionLight = new THREE.PointLight(0xffaa55, 0, 55, 2)
    scene.add(this.explosionLight)
    this.explosionLightLife = 0
  }

  addShake(v) {
    this.shake = Math.min(1.4, this.shake + v)
  }

  emit(x, y, z, opts = {}) {
    const color = tempColor.set(opts.color ?? 0xffffff).clone()
    const count = opts.count ?? 1
    for (let i = 0; i < count; i++) {
      const sp = opts.speed ?? 0
      const spread = opts.spread ?? 1
      this.glow.emit(
        x + rand(-spread, spread) * 0.1, y + rand(-spread, spread) * 0.1, z + rand(-spread, spread) * 0.1,
        (opts.vx ?? 0) + rand(-sp, sp), (opts.vy ?? 0) + rand(-sp, sp) * 0.6, (opts.vz ?? 0) + rand(-sp, sp),
        rand(opts.lifeMin ?? 0.2, opts.lifeMax ?? 0.6),
        rand(opts.sizeMin ?? 0.15, opts.sizeMax ?? 0.4),
        color,
        opts.gravity ?? 0,
        opts.drag ?? 1,
        opts.grow ?? 0,
        opts.alpha ?? 1
      )
    }
  }

  smoke(x, y, z, scale = 1) {
    const c = new THREE.Color().setHSL(0.08, 0.03, rand(0.16, 0.3)).clone()
    for (let i = 0; i < 2; i++) {
      this.smokePool.emit(
        x + rand(-0.3, 0.3), y + rand(-0.1, 0.3), z + rand(-0.3, 0.3),
        rand(-0.4, 0.4), rand(0.7, 1.5), rand(-0.4, 0.4),
        rand(0.8, 1.8), rand(0.7, 1.3) * scale, c, -0.35, 0.7, rand(1.4, 2.6) * scale, 0.85
      )
    }
  }

  fire(x, y, z, scale = 1) {
    this.emit(x, y, z, { color: 0xff7a22, count: 1, speed: 0.8, vy: 2.2, lifeMin: 0.2, lifeMax: 0.5, sizeMin: 0.5, sizeMax: 1.1, grow: 0.6, gravity: -1 })
    this.emit(x, y, z, { color: 0xffd56a, count: 1, speed: 0.3, vy: 1.8, lifeMin: 0.12, lifeMax: 0.3, sizeMin: 0.3, sizeMax: 0.6, gravity: -1 })
    if (Math.random() < 0.5) this.smoke(x, y + 0.4, z, scale * 1.2)
  }

  sparks(x, y, z, n = 8, color = 0xffd27a) {
    this.emit(x, y, z, { color, count: n, speed: 4.5, vy: 1.2, lifeMin: 0.12, lifeMax: 0.4, sizeMin: 0.06, sizeMax: 0.18, gravity: 9, drag: 1.4 })
  }

  blood(x, y, z, dir = null) {
    const c = 0x8e1717
    for (let i = 0; i < 7; i++) {
      this.smokePool.emit(
        x, y, z,
        (dir ? dir.x * 2 : 0) + rand(-1.2, 1.2), rand(0.2, 1.4), (dir ? dir.z * 2 : 0) + rand(-1.2, 1.2),
        rand(0.25, 0.6), rand(0.09, 0.2), new THREE.Color(c), 7, 0.3, 0, 0.9
      )
    }
  }

  muzzle(x, y, z) {
    const f = this.flashes[this.flashCursor]
    this.flashCursor = (this.flashCursor + 1) % this.flashes.length
    f.life = f.maxLife
    f.sprite.position.set(x, y, z)
    f.sprite.material.opacity = 1
    f.sprite.scale.setScalar(rand(1.3, 2.1))
    this.emit(x, y, z, { color: 0xffdf9a, count: 3, speed: 1.8, lifeMin: 0.05, lifeMax: 0.14, sizeMin: 0.2, sizeMax: 0.5 })
  }

  tracer(from, to, color = 0xffe6a8) {
    this.tracers.push({ from: from.clone(), to: to.clone(), life: 0.09, maxLife: 0.09, color: new THREE.Color(color) })
    if (this.tracers.length > 30) this.tracers.shift()
  }

  explosion(x, y, z) {
    this.explosionLight.position.set(x, y + 2, z)
    this.explosionLight.intensity = 220
    this.explosionLightLife = 0.35
    for (let i = 0; i < 42; i++) {
      const a = rand(0, Math.PI * 2)
      const s = rand(3, 12)
      this.emit(x, y + 0.5, z, {
        color: Math.random() < 0.5 ? 0xffb347 : 0xff5a1f,
        vx: Math.cos(a) * s, vy: rand(2, 9), vz: Math.sin(a) * s,
        lifeMin: 0.3, lifeMax: 0.9, sizeMin: 0.4, sizeMax: 1.5, grow: 2.2, gravity: 6, drag: 0.5
      })
    }
    for (let i = 0; i < 16; i++) {
      const a = rand(0, Math.PI * 2)
      this.smokePool.emit(
        x + rand(-0.6, 0.6), y + rand(0.4, 2), z + rand(-0.6, 0.6),
        Math.cos(a) * rand(1, 4), rand(2, 6), Math.sin(a) * rand(1, 4),
        rand(1.6, 3.2), rand(1.2, 2.6), new THREE.Color().setHSL(0.05, 0.05, 0.12), -0.6, 0.8, rand(2, 4), 0.9
      )
    }
    this.addShake(0.9)
  }

  update(dt) {
    this.glow.update(dt)
    this.smokePool.update(dt)
    this.shake = Math.max(0, this.shake - dt * 2.4)

    for (const f of this.flashes) {
      if (f.life > 0) {
        f.life -= dt
        f.sprite.material.opacity = Math.max(0, f.life / f.maxLife)
        if (f.life <= 0) f.sprite.material.opacity = 0
      }
    }

    // Tracers
    let ti = 0
    for (let i = this.tracers.length - 1; i >= 0; i--) this.tracers[i].life -= dt
    this.tracers = this.tracers.filter((t) => t.life > 0)
    for (const t of this.tracers) {
      if (ti >= 40) break
      this.tracerPos[ti * 6] = t.from.x
      this.tracerPos[ti * 6 + 1] = t.from.y
      this.tracerPos[ti * 6 + 2] = t.from.z
      this.tracerPos[ti * 6 + 3] = t.to.x
      this.tracerPos[ti * 6 + 4] = t.to.y
      this.tracerPos[ti * 6 + 5] = t.to.z
      const a = clamp(t.life / t.maxLife, 0, 1)
      this.tracerCol[ti * 6] = t.color.r * a
      this.tracerCol[ti * 6 + 1] = t.color.g * a
      this.tracerCol[ti * 6 + 2] = t.color.b * a
      this.tracerCol[ti * 6 + 3] = t.color.r * a
      this.tracerCol[ti * 6 + 4] = t.color.g * a
      this.tracerCol[ti * 6 + 5] = t.color.b * a
      ti++
    }
    for (let i = ti; i < 40; i++) {
      this.tracerPos.fill(0, i * 6, i * 6 + 6)
      this.tracerCol.fill(0, i * 6, i * 6 + 6)
    }
    this.tracerMesh.geometry.attributes.position.needsUpdate = true
    this.tracerMesh.geometry.attributes.color.needsUpdate = true
    this.tracerMesh.geometry.setDrawRange(0, ti * 2)

    if (this.explosionLightLife > 0) {
      this.explosionLightLife -= dt
      this.explosionLight.intensity = Math.max(0, this.explosionLight.intensity - dt * 700)
    } else {
      this.explosionLight.intensity = 0
    }
  }
}

import { clamp, formatMoney, TAU } from './utils.js'
import { GRID, CITY_EDGE } from './world.js'

const $ = (id) => document.getElementById(id)

export class HUD {
  constructor(game) {
    this.game = game
    this.el = {
      hud: $('hud'),
      health: $('health-fill'),
      armor: $('armor-fill'),
      money: $('money'),
      stars: [...document.querySelectorAll('#stars .star')],
      clock: $('clock'),
      location: $('location'),
      objTitle: $('obj-title'),
      objText: $('obj-text'),
      objDist: $('obj-dist'),
      objTimer: $('obj-timer'),
      weaponName: $('weapon-name'),
      ammo: $('ammo'),
      reload: $('reload-fill'),
      speedo: $('speedo'),
      speedValue: $('speed-value'),
      gear: $('gear'),
      prompt: $('prompt'),
      crosshair: $('crosshair'),
      toasts: $('toasts'),
      banner: $('mission-banner'),
      bannerTitle: $('banner-title'),
      bannerSub: $('banner-sub'),
      wasted: $('wasted'),
      vignette: $('vignette'),
      damageFlash: $('damage-flash'),
      hitmarker: $('hitmarker'),
      start: $('start-screen'),
      pause: $('pause-screen'),
      pauseBtn: $('pause-btn'),
      minimap: $('minimap')
    }
    this.ctx = this.el.minimap.getContext('2d')
    this.cache = {}
    this.toastTimes = []
    this.bannerTimer = 0
    this.wastedTimer = 0
    this.minimapTick = 0
    this.resizeMinimap()
    window.addEventListener('resize', () => this.resizeMinimap())
    this.toasts = []
  }

  resizeMinimap() {
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    const size = this.el.minimap.clientWidth || 180
    this.el.minimap.width = Math.round(size * dpr)
    this.el.minimap.height = Math.round(size * dpr)
    this.mapDpr = dpr
    this.mapSize = size
    this.mapR = size * 0.47
  }

  setText(key, el, value) {
    if (this.cache[key] === value) return
    this.cache[key] = value
    el.textContent = value
  }

  showStart() {
    this.el.start.classList.remove('hidden')
    this.el.hud.classList.add('hidden')
  }

  hideStart() {
    this.el.start.classList.add('hidden')
    this.el.hud.classList.remove('hidden')
  }

  showPause() { this.el.pause.classList.remove('hidden') }
  hidePause() { this.el.pause.classList.add('hidden') }

  showWasted(title = 'WASTED', sub = 'Sunset City Medical has been notified') {
    this.el.wasted.querySelector('#wasted-title').textContent = title
    this.el.wasted.querySelector('#wasted-sub').textContent = sub
    this.el.wasted.classList.remove('hidden')
    this.wastedTimer = 3.4
  }

  toast(text, type = '') {
    const div = document.createElement('div')
    div.className = 'toast ' + type
    div.textContent = text
    this.el.toasts.appendChild(div)
    this.toasts.push({ el: div, life: 3.2 })
    while (this.toasts.length > 4) {
      const old = this.toasts.shift()
      old.el.remove()
    }
  }

  banner(title, sub = '', time = 2.6) {
    this.el.bannerTitle.textContent = title
    this.el.bannerSub.textContent = sub
    this.el.banner.classList.remove('hidden')
    this.el.banner.classList.add('show')
    this.bannerTimer = time
  }

  flashDamage(amount = 0.6) {
    this.el.damageFlash.style.opacity = String(clamp(amount, 0, 1))
    this.el.vignette.classList.add('hit')
    clearTimeout(this._dmgT)
    this._dmgT = setTimeout(() => {
      this.el.damageFlash.style.opacity = '0'
      this.el.vignette.classList.remove('hit')
    }, 220)
  }

  hitmarker(kill = false) {
    this.el.hitmarker.classList.remove('show', 'kill')
    void this.el.hitmarker.offsetWidth
    this.el.hitmarker.classList.add('show')
    if (kill) this.el.hitmarker.classList.add('kill')
    clearTimeout(this._hitT)
    this._hitT = setTimeout(() => this.el.hitmarker.classList.remove('show', 'kill'), 160)
  }

  setPrompt(text) {
    if (this.cache.prompt === text) return
    this.cache.prompt = text
    this.el.prompt.textContent = text || ''
    this.el.prompt.classList.toggle('hidden', !text)
  }

  update(dt, game) {
    const p = game.player
    this.el.health.style.transform = `scaleX(${clamp(p.health / 100, 0, 1)})`
    this.el.armor.style.transform = `scaleX(${clamp(p.armor / 100, 0, 1)})`
    this.el.health.classList.toggle('low', p.health < 30)
    this.setText('money', this.el.money, formatMoney(p.money))

    const stars = Math.round(game.wanted)
    if (this.cache.stars !== stars) {
      this.cache.stars = stars
      this.el.stars.forEach((s, i) => s.classList.toggle('on', i < stars))
      this.el.stars.forEach((s) => s.classList.toggle('pulse', stars > 0))
    }
    this.setText('clock', this.el.clock, game.world.getTimeString())
    this.setText('loc', this.el.location, locName(p.pos))

    if (p.reloading) {
      const t = 1 - p.reloadTimer / p.reloadTime
      this.el.reload.style.transform = `scaleX(${clamp(t, 0, 1)})`
      this.setText('ammo', this.el.ammo, 'RELOADING')
    } else {
      this.el.reload.style.transform = 'scaleX(0)'
      this.setText('ammo', this.el.ammo, `${p.ammo} / ${p.reserve}`)
    }
    this.setText('weapon', this.el.weaponName, p.car ? 'DRIVE' : 'PISTOL')

    const driving = !!p.car
    this.el.speedo.classList.toggle('hidden', !driving)
    this.el.crosshair.classList.toggle('hidden', driving)
    if (driving) {
      this.setText('speed', this.el.speedValue, String(Math.round(p.car.speedKmh)))
      this.setText('gear', this.el.gear, p.car.speed < -0.5 ? 'R' : p.car.speed > 1 ? 'D' : 'N')
    }
    this.el.crosshair.classList.toggle('aiming', game.input.aiming && !driving)
    this.el.crosshair.style.setProperty('--spread', game.input.aiming ? '6px' : '14px')

    // Objective
    const obj = game.missions.getHudState()
    if (obj) {
      this.setText('objTitle', this.el.objTitle, obj.title)
      this.setText('objText', this.el.objText, obj.text || '')
      this.setText('objDist', this.el.objDist, obj.distance != null ? `${Math.round(obj.distance)} m` : '')
      this.setText('objTimer', this.el.objTimer, obj.timer != null ? `${Math.ceil(obj.timer)}s` : '')
      this.el.objTimer.classList.toggle('warn', obj.timer != null && obj.timer < 10)
    } else {
      this.setText('objTitle', this.el.objTitle, 'FREE ROAM')
      this.setText('objText', this.el.objText, 'Explore Sunset City. Find the gold marker to start a job.')
      this.setText('objDist', this.el.objDist, '')
      this.setText('objTimer', this.el.objTimer, '')
    }

    this.setText('prompt', this.el.prompt, this.cache.prompt) // no-op, setPrompt owns this

    // Toasts
    for (let i = this.toasts.length - 1; i >= 0; i--) {
      const t = this.toasts[i]
      t.life -= dt
      if (t.life < 0.6) t.el.style.opacity = String(clamp(t.life / 0.6, 0, 1))
      if (t.life <= 0) { t.el.remove(); this.toasts.splice(i, 1) }
    }
    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt
      if (this.bannerTimer <= 0) {
        this.el.banner.classList.add('hidden')
        this.el.banner.classList.remove('show')
      }
    }
    if (this.wastedTimer > 0) {
      this.wastedTimer -= dt
      if (this.wastedTimer <= 0) this.el.wasted.classList.add('hidden')
    }

    this.minimapTick += dt
    if (this.minimapTick > 1 / 24) {
      this.minimapTick = 0
      this.drawMinimap(game)
    }
  }

  drawMinimap(game) {
    const ctx = this.ctx
    const dpr = this.mapDpr || 1
    const size = this.mapSize || 180
    const r = this.mapR || 84
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, size, size)
    const cx = size / 2
    const cy = size / 2
    const scale = 0.8
    const yaw = game.camYaw
    const cos = Math.cos(yaw)
    const sin = Math.sin(yaw)
    const p = game.player.car ? game.player.car.pos : game.player.pos
    const px = p.x
    const pz = p.z

    const toScreen = (x, z) => {
      const dx = x - px
      const dz = z - pz
      return [cx + (dx * cos - dz * sin) * scale, cy + (dx * sin + dz * cos) * scale]
    }

    ctx.save()
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, TAU)
    ctx.clip()
    ctx.fillStyle = '#1b2024'
    ctx.fillRect(0, 0, size, size)

    // Water / beach south
    const [wx, wy] = toScreen(0, 460)
    ctx.fillStyle = '#123a46'
    ctx.fillRect(0, wy, size, size)

    // Blocks
    ctx.fillStyle = '#2c3137'
    for (let i = -5; i < 5; i++) {
      for (let j = -5; j < 5; j++) {
        const bx = GRID * i + GRID / 2
        const bz = GRID * j + GRID / 2
        const half = 26
        const corners = [
          toScreen(bx - half, bz - half),
          toScreen(bx + half, bz - half),
          toScreen(bx + half, bz + half),
          toScreen(bx - half, bz + half)
        ]
        ctx.beginPath()
        ctx.moveTo(corners[0][0], corners[0][1])
        for (let k = 1; k < 4; k++) ctx.lineTo(corners[k][0], corners[k][1])
        ctx.closePath()
        ctx.fill()
      }
    }

    // Roads
    ctx.strokeStyle = '#4b5158'
    ctx.lineWidth = 18 * scale
    for (let line = -5; line <= 5; line++) {
      const p0 = toScreen(GRID * line, -CITY_EDGE)
      const p1 = toScreen(GRID * line, CITY_EDGE)
      ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke()
      const p2 = toScreen(-CITY_EDGE, GRID * line)
      const p3 = toScreen(CITY_EDGE, GRID * line)
      ctx.beginPath(); ctx.moveTo(p2[0], p2[1]); ctx.lineTo(p3[0], p3[1]); ctx.stroke()
    }

    // Mission marker
    const missionPos = game.missions.getMarkerPos()
    if (missionPos) {
      const [mx, my] = toScreen(missionPos.x, missionPos.z)
      ctx.save()
      ctx.translate(mx, my)
      ctx.rotate(Math.PI / 4)
      ctx.fillStyle = '#ffd24a'
      ctx.strokeStyle = '#5a4300'
      ctx.lineWidth = 1.5
      ctx.fillRect(-5, -5, 10, 10)
      ctx.strokeRect(-5, -5, 10, 10)
      ctx.restore()
    }

    // Pickups
    for (const pickup of game.pickups) {
      if (pickup.taken) continue
      const [ix, iy] = toScreen(pickup.pos.x, pickup.pos.z)
      if ((ix - cx) ** 2 + (iy - cy) ** 2 > r * r) continue
      ctx.fillStyle = pickup.type === 'health' ? '#6dff8a' : pickup.type === 'armor' ? '#6db7ff' : '#ffd24a'
      ctx.beginPath(); ctx.arc(ix, iy, 2.2, 0, TAU); ctx.fill()
    }

    // Traffic
    for (const v of game.vehicles) {
      if (v.occupiedByPlayer || v.destroyed) continue
      const [vx, vy] = toScreen(v.pos.x, v.pos.z)
      if ((vx - cx) ** 2 + (vy - cy) ** 2 > r * r) continue
      ctx.fillStyle = v.police ? '#7fa8ff' : '#d7d7d7'
      ctx.fillRect(vx - 1.5, vy - 1.5, 3, 3)
    }

    // Cops
    for (const cop of game.cops) {
      if (cop.dead) continue
      const [ox, oy] = toScreen(cop.pos.x, cop.pos.z)
      if ((ox - cx) ** 2 + (oy - cy) ** 2 > r * r) continue
      ctx.fillStyle = '#ff5050'
      ctx.beginPath(); ctx.arc(ox, oy, 2.6, 0, TAU); ctx.fill()
    }
    for (const v of game.vehicles) {
      if (!v.police || v.destroyed) continue
      const [ox, oy] = toScreen(v.pos.x, v.pos.z)
      if ((ox - cx) ** 2 + (oy - cy) ** 2 > r * r) continue
      ctx.fillStyle = Math.sin(performance.now() * 0.012) > 0 ? '#ff3030' : '#3060ff'
      ctx.beginPath(); ctx.arc(ox, oy, 3.4, 0, TAU); ctx.fill()
    }

    // Player arrow
    ctx.save()
    ctx.translate(cx, cy)
    ctx.fillStyle = '#ffffff'
    ctx.strokeStyle = '#12151a'
    ctx.lineWidth = 1.4
    ctx.beginPath()
    ctx.moveTo(0, -8)
    ctx.lineTo(5.5, 6)
    ctx.lineTo(0, 3)
    ctx.lineTo(-5.5, 6)
    ctx.closePath()
    ctx.fill()
    ctx.stroke()
    ctx.restore()

    // North marker
    ctx.fillStyle = 'rgba(255,255,255,0.55)'
    ctx.font = 'bold 9px Arial'
    ctx.textAlign = 'center'
    const na = -yaw
    const nx = cx + Math.sin(na) * (r - 10)
    const ny = cy - Math.cos(na) * (r - 10)
    ctx.fillText('N', nx, ny + 3)

    ctx.restore()

    // Border
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, TAU)
    ctx.strokeStyle = 'rgba(255,255,255,0.28)'
    ctx.lineWidth = 2
    ctx.stroke()
    ctx.beginPath()
    ctx.arc(cx, cy, r + 1.5, 0, TAU)
    ctx.strokeStyle = 'rgba(0,0,0,0.55)'
    ctx.lineWidth = 2
    ctx.stroke()
  }
}

function locName(pos) {
  const beach = pos.z > 340
  if (beach) return 'Vice Beach'
  const x = pos.x
  const z = pos.z
  if (Math.abs(x) < 90 && Math.abs(z) < 90) return 'Downtown'
  if (x < -80 && z > 80) return 'West Grove'
  if (x > 120 && z < -40) return 'Casino Strip'
  if (z < -150) return 'Northside'
  if (x > 150) return 'East Docks'
  return 'Sunset City'
}

