input.content:
:root {
  --pink: #ff3f8e;
  --orange: #ff8a3d;
  --gold: #ffce4d;
  --blue: #58c8ff;
  --green: #62e07a;
  --ink: #0a0710;
  --panel: rgba(12, 11, 20, 0.64);
  --line: rgba(255, 255, 255, 0.16);
  --font-ui: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #08060e;
  color: #fff;
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

body { overscroll-behavior: none; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  cursor: crosshair;
}

.hidden { display: none !important; }

/* ---------------- START SCREEN ---------------- */

#start-screen {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(18px, 3.2vw, 44px);
  background:
    radial-gradient(120% 90% at 76% 78%, rgba(255, 99, 51, 0.28), transparent 48%),
    radial-gradient(90% 70% at 18% 22%, rgba(94, 52, 170, 0.3), transparent 62%),
    linear-gradient(100deg, rgba(6, 4, 12, 0.92) 0%, rgba(8, 5, 18, 0.56) 55%, rgba(8, 4, 14, 0.2) 100%);
  overflow: hidden;
}

#start-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,0.028) 0 1px, transparent 1px 4px);
  mix-blend-mode: overlay;
  pointer-events: none;
}

#start-screen::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 40vh;
  background: linear-gradient(0deg, rgba(5, 3, 9, 0.88), transparent);
  pointer-events: none;
}

.start-glow {
  position: absolute;
  width: 60vw;
  height: 60vw;
  right: -12vw;
  bottom: -24vw;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 79, 127, 0.26), rgba(255, 138, 61, 0.06) 44%, transparent 68%);
  filter: blur(10px);
  pointer-events: none;
}

.start-top {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.72);
}

.brand { font-weight: 800; }
.brand span { color: var(--pink); }
.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  background: rgba(8, 6, 14, 0.5);
  backdrop-filter: blur(10px);
  font-size: 9px;
  letter-spacing: 0.18em;
}
.status-pill i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #5dff8a;
  box-shadow: 0 0 10px #5dff8a;
  animation: blink 2s infinite;
}

.start-main {
  position: relative;
  z-index: 2;
  margin-top: auto;
  margin-bottom: auto;
  max-width: 900px;
  padding-top: 2vh;
}

.eyebrow {
  font-size: clamp(10px, 1vw, 13px);
  font-weight: 800;
  letter-spacing: 0.55em;
  color: var(--gold);
  text-shadow: 0 0 24px rgba(255, 191, 64, 0.55);
  margin-left: 6px;
}

.logo {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 900;
  font-size: clamp(58px, 11.4vw, 164px);
  line-height: 0.78;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  transform: skewX(-7deg);
  filter: drop-shadow(0 10px 34px rgba(0, 0, 0, 0.55));
}

.logo-sunset {
  display: block;
  background: linear-gradient(180deg, #fff1b8 0%, #ffce4d 30%, #ff7a3d 62%, #ff2f6d 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-stroke: 2px rgba(255, 148, 74, 0.12);
}

.logo-city {
  display: block;
  margin-left: clamp(30px, 6vw, 100px);
  color: #f7f4ec;
  text-shadow:
    0 0 42px rgba(255, 63, 142, 0.32),
    0 4px 0 rgba(0, 0, 0, 0.32);
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.1);
}

.tagline {
  margin: 22px 0 0 6px;
  max-width: 520px;
  font-size: clamp(13px, 1.25vw, 17px);
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.72);
  letter-spacing: 0.01em;
}

.start-actions {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  margin: 34px 0 0 4px;
}

#play-btn {
  position: relative;
  appearance: none;
  border: 0;
  padding: 18px 54px 17px;
  border-radius: 4px;
  font-family: var(--font-display);
  font-size: clamp(16px, 1.5vw, 20px);
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #1a0710;
  background: linear-gradient(180deg, #ffe9a8, #ffce4d 38%, #ff9c3f 100%);
  box-shadow:
    0 0 0 1px rgba(255, 233, 168, 0.85),
    0 8px 0 #8c3d13,
    0 18px 50px rgba(255, 137, 49, 0.42);
  cursor: pointer;
  transform: skewX(-6deg);
  transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s;
}
#play-btn::after {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(84, 30, 0, 0.32);
  border-radius: 2px;
  pointer-events: none;
}
#play-btn:hover {
  transform: skewX(-6deg) translateY(-2px) scale(1.02);
  filter: saturate(1.15) brightness(1.05);
  box-shadow:
    0 0 0 1px rgba(255, 233, 168, 0.95),
    0 10px 0 #8c3d13,
    0 24px 70px rgba(255, 137, 49, 0.6);
}
#play-btn:active { transform: skewX(-6deg) translateY(4px); box-shadow: 0 3px 0 #8c3d13, 0 8px 30px rgba(255, 137, 49, 0.4); }

.start-note {
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.42);
}

.start-bottom {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 26px;
  flex-wrap: wrap;
}

.control-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(120px, 1fr));
  gap: 10px 26px;
  padding: 16px 20px;
  background: rgba(8, 6, 15, 0.42);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 2px solid var(--pink);
  backdrop-filter: blur(14px);
}

.control { display: flex; align-items: center; gap: 10px; font-size: 10.5px; color: rgba(255,255,255,0.58); letter-spacing: 0.04em; }
.control kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  height: 24px;
  padding: 0 7px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.09);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom-color: rgba(255, 255, 255, 0.35);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.start-meta {
  display: flex;
  gap: 10px;
  padding-bottom: 4px;
  font-size: 9px;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.3);
}

/* ---------------- HUD ---------------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  font-family: var(--font-ui);
  text-transform: uppercase;
}

#objective {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  left: max(20px, env(safe-area-inset-left));
  width: min(310px, 34vw);
  padding: 13px 16px 14px 18px;
  background: linear-gradient(100deg, rgba(10, 8, 18, 0.8), rgba(12, 9, 22, 0.42));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-left: 3px solid var(--gold);
  backdrop-filter: blur(12px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.26);
}

.obj-kicker {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: var(--gold);
  margin-bottom: 3px;
}
#obj-title {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 18px;
  letter-spacing: 0.015em;
  line-height: 1.05;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.5);
}
#obj-text {
  margin-top: 5px;
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: 0.035em;
  color: rgba(255, 255, 255, 0.66);
  text-transform: none;
}
.obj-meta {
  margin-top: 7px;
  display: flex;
  gap: 12px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.82);
  min-height: 12px;
}
#obj-timer { color: var(--orange); }
#obj-timer.warn { color: #ff4f4f; animation: blink 0.6s infinite; }

#status {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
