  pillarL.position.set(-w * 0.41, bodyY + bodyH / 2 + cabH / 2, -l * cabL * 0.5)
  group.add(pillarL)
  const pillarR = pillarL.clone()
  pillarR.position.x = w * 0.41
  group.add(pillarR)

  const bumperF = new THREE.Mesh(new THREE.BoxGeometry(w * 0.98, 0.16, 0.18), trim)
  bumperF.position.set(0, 0.4, l / 2 + 0.04)
